#!/usr/bin/env python3
# AI-hint: Inventories every version token in the repo and classifies it as SSOT-definition, SSOT-derived placeholder, or hardcoded literal, emitting the version-literals audit TSV that drives the WS-FLOAT campaign.
# AI-related: usr/share/mios/reference/version-literals-audit.tsv, usr/share/mios/mios.toml, automation/98-drift-checks.sh
# AI-functions: classify_line, suggest_ssot_key, scan_repo, main
"""
tools/audit-version-literals.py -- Audit & inventory version tokens across MiOS repo.
Classifies version literals as:
  (a) SSOT-definition
  (b) SSOT-derived/placeholder
  (c) HARDCODED-literal

Emits usr/share/mios/reference/version-literals-audit.tsv
"""

import os
import re
import sys
from pathlib import Path

VERSION_REGEX = re.compile(
    r'(:v?\d+\.\d+(?:\.\d+)?|stable:/v\d+\.\d+|fedora-\d+|@sha256:[a-f0-9]{64}|==\d+\.\d+(?:\.\d+)?|rancher/k3s:v\d+\.\d+\.\d+(?:-[a-z0-9]+)?)'
)

SKIP_DIRS = {
    ".git", ".cargo", ".rustup", "__pycache__", "node_modules", "vendor",
    "target", ".tmp.drivedownload", ".tmp.driveupload", "artifacts", "root",
    "usr/share/doc", "tmp"
}

EXEMPT_EXTENSIONS = {
    ".lock", ".csv", ".tsv", ".sum", ".log", ".diff", ".png", ".jpg", ".gz", ".md"
}

def classify_line(file_path: str, line: str, token: str) -> str:
    norm_path = file_path.replace('\\', '/')

    # (a) SSOT-definition
    if "usr/share/mios/mios.toml" in norm_path or norm_path == "mios.toml":
        return "SSOT-definition"

    # (b) SSOT-derived / placeholder
    if "${" in line or "$MIOS_" in line or "$FEDORA_VERSION" in line or "env_var" in line:
        return "SSOT-derived/placeholder"

    # (c) HARDCODED-literal
    return "HARDCODED-literal"

def suggest_ssot_key(token: str) -> str:
    if "k3s" in token or "k8s" in token or "stable:/v" in token:
        return "MIOS_K3S_VERSION"
    if "fedora-" in token:
        return "FEDORA_VERSION"
    if "==" in token:
        return "PYTHON_DEP_VERSION"
    return "MIOS_VERSION_SSOT"

def scan_repo(repo_root):
    records = []
    class_counts = {"SSOT-definition": 0, "SSOT-derived/placeholder": 0, "HARDCODED-literal": 0}

    for root, dirs, files in os.walk(repo_root):
        # Prune skipped directories
        dirs[:] = [d for d in dirs if d not in SKIP_DIRS and not d.startswith('.')]

        rel_root = os.path.relpath(root, repo_root).replace('\\', '/')
        if rel_root == ".":
            rel_root = ""

        for f in files:
            ext = os.path.splitext(f)[1].lower()
            if ext in EXEMPT_EXTENSIONS or f == "version-literals-audit.tsv":
                continue

            rel_path = f"{rel_root}/{f}" if rel_root else f
            abs_path = os.path.join(root, f)

            try:
                with open(abs_path, 'r', encoding='utf-8', errors='ignore') as fh:
                    for line_idx, line in enumerate(fh, 1):
                        matches = VERSION_REGEX.findall(line)
                        for match in matches:
                            cls = classify_line(rel_path, line, match)
                            class_counts[cls] = class_counts.get(cls, 0) + 1
                            sugg = suggest_ssot_key(match)
                            records.append((rel_path, str(line_idx), match, cls, sugg))
            except Exception:
                continue

    # Sort deterministically
    records.sort(key=lambda r: (r[0], int(r[1]), r[2]))
    return records, class_counts

def main():
    repo_root = Path(__file__).resolve().parent.parent
    output_tsv = repo_root / "usr/share/mios/reference/version-literals-audit.tsv"
    output_tsv.parent.mkdir(parents=True, exist_ok=True)

    records, class_counts = scan_repo(repo_root)

    lines = ["path\tline\ttoken\tclass\tsuggested_ssot_key\n"]
    for rec in records:
        lines.append("\t".join(rec) + "\n")

    output_tsv.write_text("".join(lines), encoding="utf-8")

    print(f"[audit-version-literals] Audit complete ({len(records)} findings). Output written to {output_tsv}")
    print(f"[audit-version-literals] Summary of classes:")
    for cls, count in sorted(class_counts.items()):
        print(f"  {cls}: {count}")

if __name__ == "__main__":
    main()

#!/usr/bin/env python3
# AI-hint: Drift check helper to verify resolver twin equivalence between mios_toml.py and userenv.sh.
# AI-related: usr/lib/mios/mios_toml.py, usr/lib/mios/userenv.sh, automation/98-drift-checks.sh
# AI-functions: main

import os
import sys
import re
import json
import subprocess
import shlex

def main():
    root = os.environ.get("MIOS_DRIFT_ROOT")
    if not root:
        root = os.path.abspath(os.path.join(os.path.dirname(__file__), ".."))

    os.environ["MIOS_VENDOR_TOML"] = os.path.join(root, "usr/share/mios/mios.toml").replace('\\', '/')
    os.environ["MIOS_HOST_TOML"] = os.path.join(root, "etc/mios/mios.toml").replace('\\', '/')
    os.environ["MIOS_USER_TOML"] = os.path.join(root, "nonexistent.toml").replace('\\', '/')
    os.environ["MIOS_VENDOR_TOML_D"] = os.path.join(root, "usr/lib/mios/mios.d").replace('\\', '/')
    os.environ["MIOS_HOST_TOML_D"] = os.path.join(root, "etc/mios/mios.d").replace('\\', '/')
    os.environ["MIOS_USER_TOML_D"] = os.path.join(root, "nonexistent_d").replace('\\', '/')

    lib_path = os.path.abspath(os.path.join(os.path.dirname(__file__), "../usr/lib/mios"))
    sys.path.insert(0, lib_path)
    if root:
        alt_path = os.path.join(root, "usr/lib/mios")
        if os.name == "nt" and alt_path.startswith("/mnt/c/"):
            alt_path = "C:/" + alt_path[7:]
        sys.path.insert(0, alt_path)
    try:
        import mios_toml
    except ImportError as e:
        print(f"Error: Could not import mios_toml: {e}", file=sys.stderr)
        sys.exit(1)

    env = os.environ.copy()

    # Strip INHERITED MIOS_* before running the bash twin. The comparison asks
    # "what does userenv.sh resolve from SSOT?", but bash reports every MIOS_*
    # in its environment -- so any ambient var the TOML side has no key for
    # shows up as a mismatch. CI sets MIOS_DRIFT_REQUIRE_TOOLS=1 as a workflow
    # knob, which failed the check with:
    #   Var MIOS_DRIFT_REQUIRE_TOOLS: Toml resolved '', Bash resolved '1'
    # Keep only the tier pointers the resolver needs to find the SSOT layers.
    _TIER_VARS = {
        "MIOS_ROOT", "MIOS_TOML", "MIOS_TOML_ROOT",
        "MIOS_VENDOR_TOML", "MIOS_VENDOR_TOML_D",
        "MIOS_HOST_TOML", "MIOS_HOST_TOML_D",
        "MIOS_USER_TOML", "MIOS_USER_TOML_D",
    }
    for _k in [k for k in env if k.startswith("MIOS_") and k not in _TIER_VARS]:
        env.pop(_k, None)

    env["MSYS_NO_PATHCONV"] = "1"
    env["PYTHONPATH"] = os.path.join(root, "usr/lib/mios").replace('\\', '/') + (os.pathsep + env["PYTHONPATH"] if "PYTHONPATH" in env else "")
    env.pop("MIOS_TOML_RESOLVED", None)

    bash_exe = "bash"
    if os.name == "nt":
        for path in [r"C:\Program Files\Git\bin\bash.exe", r"C:\Program Files\Git\usr\bin\bash.exe"]:
            if os.path.exists(path):
                bash_exe = path
                break

    userenv_script = os.path.join(root, 'usr/lib/mios/userenv.sh').replace('\\', '/')
    py_exec = sys.executable.replace('\\', '/')
    cmd = [
        bash_exe, "-c",
        f"source {shlex.quote(userenv_script)} && {shlex.quote(py_exec)} -c \"import os, json; print(json.dumps({{k: v for k, v in os.environ.items() if k.startswith('MIOS_')}}))\""
    ]
    try:
        out = subprocess.check_output(cmd, env=env, stderr=subprocess.STDOUT).decode("utf-8")
        print(f"BASH OUTPUT: {out}", file=sys.stderr)
        bash_vars = json.loads(out)
    except subprocess.CalledProcessError as e:
        print("Error: userenv.sh execution failed:\n", e.output.decode("utf-8", errors="ignore"), file=sys.stderr)
        sys.exit(1)
    except json.JSONDecodeError as e:
        print(f"Error: Failed to parse env JSON: {e}\nOutput was:\n{out}", file=sys.stderr)
        sys.exit(1)

    merged_data = mios_toml.load_merged()
    stack_id = mios_toml.get("ports", "stack_id")
    try:
        stack_offset = int(stack_id) * 10000 if stack_id is not None else 0
    except ValueError:
        stack_offset = 0

    get_aliases = mios_toml.get_aliases
    def process_val(dotted, v):
        return mios_toml.process_val(dotted, v, stack_offset)
    walk = mios_toml.walk

    toml_vars = {}

    all_pairs = []
    EXCLUDED_SECTIONS = mios_toml.EXCLUDED_SECTIONS
    for sec, val in merged_data.items():
        if isinstance(val, dict) and sec not in EXCLUDED_SECTIONS:
            all_pairs.extend(walk(val, sec))

    WALK_MOSTLY_DEAD = mios_toml.WALK_MOSTLY_DEAD
    WALK_EMIT_KEEP = mios_toml.WALK_EMIT_KEEP

    exports_map = {}
    for path, val in all_pairs:
        val_processed = process_val(path, val)
        if val_processed is None or val_processed == "":
            continue
        if path.startswith("converge."):
            _cbody = "CONV_" + path[len("converge."):].upper().replace(".", "_").replace("-", "_").replace("/", "_")
        else:
            _cbody = path.upper().replace(".", "_").replace("-", "_").replace("/", "_")
        canonical = _cbody if _cbody.startswith("MIOS_") else "MIOS_" + _cbody
        sec_name = path.split(".", 1)[0]
        if sec_name in WALK_MOSTLY_DEAD and canonical not in WALK_EMIT_KEEP:
            pass
        else:
            exports_map[canonical] = str(val_processed)

        for leg in get_aliases(path):
            if leg.endswith("_VERSION") and path.startswith("image.sidecars."):
                exports_map[leg] = str(val_processed).rsplit(":", 1)[1] if ":" in str(val_processed) else "latest"
            else:
                exports_map[leg] = str(val_processed)

    env_tbl = mios_toml.section(merged_data, "env")
    if isinstance(env_tbl, dict):
        for k, v in sorted(env_tbl.items()):
            vp = process_val("env." + k, v)
            if vp is not None and vp != "":
                exports_map[k] = str(vp)

    ref_path = os.path.join(root, "usr/share/mios/referenced_names.txt")
    if os.path.isfile(ref_path):
        try:
            with open(ref_path, "r", encoding="utf-8") as f:
                for line in f:
                    v = line.strip()
                    if v and v not in exports_map:
                        exports_map[v] = ""
        except Exception:
            pass

    toml_vars = exports_map

    loopback = mios_toml.get("pgvector", "listen_loopback")
    if loopback is None:
        loopback = True
    toml_vars["MIOS_PG_BIND_ADDR"] = "127.0.0.1" if loopback else "0.0.0.0"

    ignore_vars = {
        "MIOS_VENDOR_TOML", "MIOS_HOST_TOML", "MIOS_USER_TOML",
        "MIOS_VENDOR_TOML_D", "MIOS_HOST_TOML_D", "MIOS_USER_TOML_D",
        "MIOS_DRIFT_ROOT", "MIOS_DRIFT_CHECK_ROOT", "MIOS_DRIFT_CHECK_SOFT",
        "MIOS_TOML_ROOT", "MIOS_ROOT_LIB", "MIOS_CONFIG_DIR", "MIOS_ROOT"
    }

    # AGY-1171: 3-way crate == python == bash assertion when mios-resolver binary exists
    bin_path = os.path.join(root, "tools/native/target/debug/mios-resolver.exe" if os.name == "nt" else "tools/native/target/debug/mios-resolver")
    crate_vars = {}
    if os.path.isfile(bin_path):
        try:
            crate_out = subprocess.check_output([bin_path, "--emit=json"], env=env, stderr=subprocess.STDOUT).decode("utf-8")
            crate_data = json.loads(crate_out)
            # Flatten crate json to env vars format
            for sec, tval in crate_data.items():
                if isinstance(tval, dict):
                    for k, v in tval.items():
                        var_key = f"MIOS_{sec.upper()}_{k.upper().replace('-', '_')}"
                        crate_vars[var_key] = str(v)
        except Exception:
            pass

    mismatches = []
    for k, expected in sorted(toml_vars.items()):
        if k in ignore_vars:
            continue
        actual = bash_vars.get(k)
        if actual != expected:
            if expected == "" and (actual is None or actual == ""):
                continue
            mismatches.append(f"Var {k}: Toml resolved {expected!r}, Bash resolved {actual!r}")

    for k, actual in sorted(bash_vars.items()):
        if k in ignore_vars:
            continue
        if k not in toml_vars:
            mismatches.append(f"Unexpected Var {k}: Bash resolved {actual!r}, Toml has no entry")

    if mismatches:
        for m in mismatches:
            print(f"  [resolver-twin] {m}", file=sys.stderr)
        sys.exit(1)

    print("SUCCESS: resolvers are equivalent!")
    sys.exit(0)

if __name__ == "__main__":
    main()

#!/usr/bin/env python3
# AI-hint: Golden round-trip compiler for templates -- verifies all templates parse cleanly.
# AI-related: usr/share/mios/templates/
# AI-functions: main, compile_template

import os
import sys
import json
import subprocess

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
os.environ["MIOS_TOML_ROOT"] = ROOT
os.environ["MIOS_THEME_ROOT"] = ROOT
sys.path.insert(0, os.path.join(ROOT, "usr/lib/mios"))
import mios_toml

def load_mock_vals():
    cfg = mios_toml.load_merged()
    placeholders = cfg.get("templates", {}).get("placeholders", {})
    if placeholders:
        return placeholders
    return {
        "name": "mockname",
        "PascalName": "MockName",
        "date": "2026-07-17",
        "id": "9999",
        "title": "Mock Title",
        "description": "Mock Description",
        "status": "proposed",
        "priority": "P1",
        "theme": "Mock Theme",
        "task_title": "Mock Task Title",
        "task_id": "8888",
        "image": "mock-image:latest",
        "uid": "1000",
        "gid": "1000",
        "filename": "mockname.py",
        "path": "usr/lib/mios/agent-pipe/mios_pipe/mockname.py",
    }

MOCK_VALS = load_mock_vals()

def compile_template(name, content):
    rendered = content
    for k, v in MOCK_VALS.items():
        rendered = rendered.replace(f"{{{{{k}}}}}", v)

    if name in ("python-module", "python-test", "python-tool"):
        try:
            compile(rendered, name, "exec")
        except SyntaxError as e:
            return f"Python SyntaxError: {e}"

    elif name in ("json-schema",):
        try:
            json.loads(rendered)
        except json.JSONDecodeError as e:
            return f"JSON Parse Error: {e}"

    elif name in ("toml-config",):
        try:
            import tomllib
            tomllib.loads(rendered)
        except ImportError:
            try:
                import tomli
                tomli.loads(rendered)
            except ImportError:
                pass
        except Exception as e:
            return f"TOML Parse Error: {e}"

    elif name in ("yaml",):
        try:
            import yaml
            yaml.safe_load(rendered)
        except ImportError:
            for i, line in enumerate(rendered.splitlines()):
                if ":" in line and not line.strip().startswith("#"):
                    parts = line.split(":", 1)
                    if not parts[0].strip():
                        return f"YAML Indentation/Syntax validation fallback failed at line {i+1}"
        except Exception as e:
            return f"YAML Parse Error: {e}"

    elif name in ("bash", "bash-verb", "drift-check", "automation-step"):
        if os.name != "nt":
            try:
                r = subprocess.run(["bash", "-n"], input=rendered, text=True, capture_output=True, timeout=5)
                if r.returncode != 0:
                    return f"Bash syntax check failed: {r.stderr.strip()}"
            except Exception:
                pass

    return None

def _try_native_bin(args_list):
    bin_path = os.environ.get("MIOS_TCOMPILE_BIN")
    if not bin_path:
        exe = "mios-template-compile.exe" if os.name == "nt" else "mios-template-compile"
        for profile in ("release", "debug"):
            candidate = os.path.join(ROOT, "tools/native/target", profile, exe)
            if os.path.isfile(candidate):
                bin_path = candidate
                break
    if bin_path and os.path.isfile(bin_path):
        try:
            res = subprocess.run([bin_path] + args_list, stdout=sys.stdout, stderr=sys.stderr)
            sys.exit(res.returncode)
        except Exception:
            pass

def main():
    _try_native_bin(sys.argv[1:])
    templates_dir = os.path.join(ROOT, "usr/share/mios/templates")
    if not os.path.isdir(templates_dir):
        sys.stderr.write(f"Templates directory not found: {templates_dir}\n")
        return 1

    merged = mios_toml.load_merged()
    templates_cfg = merged.get("templates", {})

    failures = {}
    success_count = 0

    for fn in sorted(os.listdir(templates_dir)):
        full_path = os.path.join(templates_dir, fn)
        if os.path.isdir(full_path) or fn.startswith(".") or fn == "conformance-grandfathered.list":
            continue

        if fn not in templates_cfg:
            failures[fn] = "Not registered in mios.toml [templates.*]"
            continue

        path = os.path.join(templates_dir, fn)
        with open(path, "r", encoding="utf-8") as f:
            content = f.read()

        err = compile_template(fn, content)
        if err:
            failures[fn] = err
        else:
            success_count += 1

    if failures:
        sys.stderr.write(f"[compile-templates] FAIL: {len(failures)} template(s) failed compilation/validation:\n")
        for fn, err in failures.items():
            sys.stderr.write(f"    {fn}: {err}\n")
        return 1

    print(f"[compile-templates] PASS: All {success_count} templates compiled/validated successfully.")
    return 0

if __name__ == "__main__":
    sys.exit(main())

# AI-hint: A migration script that replaces a broken manual ReadKey loop with Read-Host -MaskInput in mios-build-local.ps1 to ensure pasted tokens are correctly captured in PowerShell 7.x.
# AI-related: mios-build-local
<#
.SYNOPSIS  Fix token paste bug in mios-build-local.ps1
.DESCRIPTION
    The [Console]::ReadKey loop doesn't detect Enter after paste in PS 7.6.
    Replace with Read-Host -MaskInput (PS 7.1+, handles paste natively).

    Run from repo root:
      cd $env:USERPROFILE\OneDrive\Documents\GitHub\MiOS   # or wherever the repo is
      .\fix-token-input.ps1
#>
$ErrorActionPreference = "Stop"

if (-not (Test-Path "mios-build-local.ps1")) {
    Write-Host "  ERROR: Run from \MiOS repo root" -ForegroundColor Red; exit 1
}

$file = "mios-build-local.ps1"
$content = [System.IO.File]::ReadAllText((Resolve-Path $file).Path)

# Old: custom ReadKey loop that breaks on paste
$old = @'
        if ($Secret) {
            $secBuf = ""
            while ($true) {
                $key = [Console]::ReadKey($true)
                if ($key.Key -eq 'Enter') { Write-Host ""; break }
                if ($key.Key -eq 'Backspace') {
                    if ($secBuf.Length -gt 0) { $secBuf = $secBuf.Substring(0, $secBuf.Length - 1); Write-Host "`b `b" -NoNewline }
                } else {
                    $secBuf += $key.KeyChar; Write-Host "*" -NoNewline
                }
            }
            $buf = $secBuf
'@

# New: Read-Host -MaskInput (PS 7.1+, handles paste correctly)
$new = @'
        if ($Secret) {
            $buf = Read-Host -MaskInput
'@

if ($content.Contains($old)) {
    $content = $content.Replace($old, $new)
    [System.IO.File]::WriteAllText(
        (Resolve-Path $file).Path, $content,
        [System.Text.UTF8Encoding]::new($true)  # BOM for PS file
    )
    Write-Host "  [ok] Token input fixed: Read-Host -MaskInput (handles paste)" -ForegroundColor Green
} else {
    # Try with normalized line endings
    $content = $content -replace "`r`n", "`n"
    $old = $old -replace "`r`n", "`n"
    $new = $new -replace "`r`n", "`n"
    if ($content.Contains($old)) {
        $content = $content.Replace($old, $new)
        [System.IO.File]::WriteAllText(
            (Resolve-Path $file).Path, $content,
            [System.Text.UTF8Encoding]::new($true)
        )
        Write-Host "  [ok] Token input fixed (LF normalized)" -ForegroundColor Green
    } else {
        Write-Host "  [x] ReadKey pattern not found -- checking manually" -ForegroundColor Red
        Write-Host "  Line 91:" -ForegroundColor Yellow
        Get-Content $file | Select-Object -Skip 90 -First 1
    }
}

git add mios-build-local.ps1
git commit -m "fix: token paste bug -- replace ReadKey loop with Read-Host -MaskInput`n`n[Console]::ReadKey loop in Read-Timed -Secret doesn't detect Enter`nafter paste in PowerShell 7.6/Windows Terminal. Each Enter press`nadds another masked character instead of submitting.`n`nRead-Host -MaskInput (PS 7.1+) handles paste, Enter, backspace`nnatively with * masking."
git push origin main 2>&1 | ForEach-Object { Write-Host "  $_" }
if ($LASTEXITCODE -eq 0) {
    Write-Host "`n  [ok] Pushed. Re-clone and rebuild.`n" -ForegroundColor Green
}

#!/usr/bin/env python3
# AI-hint: Generates a machine-readable module-boundary manifest for the agent-pipe DI contract.
import ast
import json
import os
import sys

def main():
    root = os.path.abspath(os.path.join(os.path.dirname(__file__), ".."))
    pipe_dir = os.path.join(root, "usr", "lib", "mios", "agent-pipe", "mios_pipe")
    out_json = os.path.join(root, "usr", "share", "mios", "pipe-boundaries.manifest.json")

    manifest = {"modules": {}}

    if os.path.isdir(pipe_dir):
        for r, ds, fs in os.walk(pipe_dir):
            for f in sorted(fs):
                if f.endswith(".py") and not f.startswith("test_"):
                    fpath = os.path.join(r, f)
                    rel_path = os.path.relpath(fpath, root).replace("\\", "/")
                    try:
                        with open(fpath, "r", encoding="utf-8") as fh:
                            tree = ast.parse(fh.read(), filename=fpath)

                        config_kwargs = []
                        public_symbols = []

                        for node in ast.walk(tree):
                            if isinstance(node, ast.FunctionDef):
                                if node.name == "configure":
                                    for arg in node.args.kwonlyargs:
                                        config_kwargs.append(arg.arg)
                                elif not node.name.startswith("_"):
                                    public_symbols.append(node.name)
                            elif isinstance(node, ast.ClassDef) and not node.name.startswith("_"):
                                public_symbols.append(node.name)

                        if config_kwargs or public_symbols:
                            manifest["modules"][rel_path] = {
                                "configure_kwargs": sorted(config_kwargs),
                                "public_symbols": sorted(public_symbols),
                            }
                    except Exception as e:
                        print(f"WARN: Failed to parse {rel_path}: {e}", file=sys.stderr)

    os.makedirs(os.path.dirname(out_json), exist_ok=True)
    with open(out_json, "w", encoding="utf-8") as fh:
        json.dump(manifest, fh, indent=2, sort_keys=True)
        fh.write("\n")

    print(f"[gen-pipe-boundary-manifest] Emitted {out_json} with {len(manifest['modules'])} modules.")

if __name__ == "__main__":
    main()

# AI-hint: Parses Markdown files and metadata blocks to generate a JSON manifest of the project structure, providing agents with a searchable index of documentation, knowledge blocks, and file metadata.
# AI-functions: parse_markdown_metadata, generate_json_manifest, generate_gzipped_manifest
import os
import json
import re
import gzip
import subprocess

def parse_markdown_metadata(content):
    """Simple parser to extract title and metadata from Markdown."""
    title_match = re.search(r'^#\s+(.+)$', content, re.MULTILINE)
    title = title_match.group(1).strip() if title_match else "Untitled"

    metadata = {}
    meta_matches = re.findall(r'^>\s+\*\*(.+?):\*\*\s+(.+)$', content, re.MULTILINE)
    for key, value in meta_matches:
        metadata[key.strip().lower().replace(" ", "_")] = value.strip()

    knowledge_block = {}
    kb_match = re.search(r'```json:knowledge\s*\n(.*?)\n```', content, re.DOTALL)
    if kb_match:
        try:
            knowledge_block = json.loads(kb_match.group(1))
        except json.JSONDecodeError:
            pass

    return title, metadata, knowledge_block

_TRACKED_CACHE = None


def tracked_files():
    """Repo-relative paths git tracks, or None when git is unavailable.

    The manifests embed a walk of the tree. Walking the FILESYSTEM makes the
    output a function of the developer's working directory -- local scratch
    files, .bak files and untracked notes all land in root-manifest.json -- so
    a manifest generated on a dev box can never match one regenerated on a
    clean CI checkout, and check_ai_manifests_fresh fails forever. Restricting
    the walk to tracked files makes the artifact reproducible anywhere.
    """
    global _TRACKED_CACHE
    if _TRACKED_CACHE is None:
        try:
            out = subprocess.run(["git", "ls-files"], capture_output=True,
                                 text=True, check=True).stdout
            _TRACKED_CACHE = {p.strip() for p in out.split("\n") if p.strip()}
        except Exception:
            _TRACKED_CACHE = set()
    return _TRACKED_CACHE or None


def _is_tracked(rel_path):
    known = tracked_files()
    return known is None or rel_path in known


def generate_json_manifest(target_dir, output_file, recursive=True, ignore_dirs=None):
    if ignore_dirs is None:
        ignore_dirs = {".git", ".venv", "output", "__pycache__", "agents/research", "node_modules", "target", "dist", "build", ".system_generated", "scratch", "logs"}

    manifest = {
        "source_directory": target_dir,
        "entries": []
    }

    if not os.path.exists(target_dir):
        return

    for root, dirs, files in os.walk(target_dir):
        if not recursive and root != target_dir:
            continue

        dirs[:] = sorted(d for d in dirs if d not in ignore_dirs)

        for file in sorted(files):
            if file.startswith(os.path.basename(output_file).replace(".tmp", "")) or file.endswith(".tmp"):
                continue

            file_path = os.path.join(root, file)
            rel_path = os.path.relpath(file_path, start=os.getcwd()).replace('\\', '/')
            if not _is_tracked(rel_path):
                continue

            try:
                entry = {
                    "path": rel_path
                }

                if file.endswith(".md"):
                    with open(file_path, 'r', encoding='utf-8') as f:
                        content = f.read()
                    title, metadata, knowledge_block = parse_markdown_metadata(content)
                    entry.update({
                        "title": title,
                        "type": "documentation",
                        "metadata": metadata,
                        "knowledge": knowledge_block,
                        "content_preview": content[:500] + "..." if len(content) > 500 else content,
                        "full_content": content
                    })
                    manifest["entries"].append(entry)
                elif file.endswith(".json"):
                    with open(file_path, 'r', encoding='utf-8') as f:
                        try:
                            data = json.load(f)
                            title = file
                            if isinstance(data, dict):
                                title = data.get("artifact_name", file)
                            entry.update({
                                "title": title,
                                "type": "structured_data",
                                "structured_data": data
                            })
                            manifest["entries"].append(entry)
                        except json.JSONDecodeError:
                            continue
                elif file.endswith((".sh", ".ps1", ".py", ".toml", "Containerfile", "Justfile")):
                    with open(file_path, 'r', encoding='utf-8') as f:
                        try:
                            content = f.read()
                            entry.update({
                                "title": file,
                                "type": "source_code",
                                "full_content": content
                            })
                            manifest["entries"].append(entry)
                        except UnicodeDecodeError:
                            continue
            except (FileNotFoundError, PermissionError, OSError):
                continue

    with open(output_file, 'w', encoding='utf-8') as f:
        json.dump(manifest, f, indent=2)
    print(f"Generated {output_file}")

def generate_gzipped_manifest(target_dir, output_file, recursive=True, ignore_dirs=None):
    if ignore_dirs is None:
        ignore_dirs = {".git", ".venv", "output", "__pycache__", "agents/research", "node_modules", "target", "dist", "build", ".system_generated", "scratch", "logs"}

    manifest = {
        "source_directory": target_dir,
        "entries": []
    }

    if not os.path.exists(target_dir):
        return

    for root, dirs, files in os.walk(target_dir):
        if not recursive and root != target_dir:
            continue

        dirs[:] = sorted(d for d in dirs if d not in ignore_dirs)

        for file in sorted(files):
            if file.startswith(os.path.basename(output_file).replace(".tmp", "")) or file.endswith(".tmp"):
                continue

            file_path = os.path.join(root, file)
            rel_path = os.path.relpath(file_path, start=os.getcwd()).replace('\\', '/')
            if not _is_tracked(rel_path):
                continue

            try:
                entry = {
                    "path": rel_path
                }

                if file.endswith(".json.gz"):
                    with gzip.open(file_path, 'rt', encoding='utf-8') as f:
                        try:
                            data = json.load(f)
                            title = file
                            if isinstance(data, dict):
                                title = data.get("artifact_name", file)
                            entry.update({
                                "title": title,
                                "type": "structured_data",
                                "structured_data": data
                            })
                            manifest["entries"].append(entry)
                        except json.JSONDecodeError:
                            continue
                elif file.endswith(".json"):
                    with open(file_path, 'r', encoding='utf-8') as f:
                        try:
                            data = json.load(f)
                            title = file
                            if isinstance(data, dict):
                                title = data.get("artifact_name", file)
                            entry.update({
                                "title": title,
                                "type": "structured_data",
                                "structured_data": data
                            })
                            manifest["entries"].append(entry)
                        except json.JSONDecodeError:
                            continue
            except (FileNotFoundError, PermissionError, OSError, UnicodeDecodeError):
                continue

    with gzip.open(output_file, 'wt', encoding='utf-8') as f:
        json.dump(manifest, f, indent=2)
    print(f"Generated {output_file}")

if __name__ == "__main__":
    import sys

    check_mode = "--check" in sys.argv

    targets = [
        ("specs", "specs/manifest.json", False), # Non-recursive for flat specs (Wiki)
        (".ai/foundation/memories", ".ai/foundation/memories/manifest.json", False),
        ("artifacts", "artifacts/manifest.json.gz", False),
        ("automation", "automation/manifest.json", True),
        ("tools", "tools/manifest.json", True),
        ("overlay", "manifest.json", True),
        ("evals", "evals/manifest.json", True),
        ("bib-configs", "bib-configs/manifest.json", True),
        ("agents/research", "agents/research/manifest.json", True),
        (".", "root-manifest.json", False) # Non-recursive for root
    ]

    has_drift = False

    for target_dir, output_file, recursive in targets:
        if not os.path.exists(target_dir):
            continue

        # Only GATE manifests that are actually committed. root-manifest.json
        # is covered by the `/*` rule in .gitignore, so a clean CI checkout
        # never has it and --check reported "Missing manifest file" forever.
        # It is still WRITTEN in normal mode; it just cannot be a gate subject.
        if check_mode:
            known = tracked_files()
            if known is not None and output_file not in known:
                continue

        if check_mode:
            temp_file = output_file + ".tmp"
            if output_file.endswith(".gz"):
                generate_gzipped_manifest(target_dir, temp_file, recursive)
            else:
                generate_json_manifest(target_dir, temp_file, recursive)

            try:
                if os.path.exists(output_file):
                    if output_file.endswith(".gz"):
                        with gzip.open(output_file, 'rt', encoding='utf-8') as f1, gzip.open(temp_file, 'rt', encoding='utf-8') as f2:
                            d1 = f1.read()
                            d2 = f2.read()
                    else:
                        with open(output_file, 'r', encoding='utf-8') as f1, open(temp_file, 'r', encoding='utf-8') as f2:
                            d1 = f1.read()
                            d2 = f2.read()
                    if d1 != d2:
                        print(f"[generate-ai-manifest] Manifest drift detected: {output_file}", file=sys.stderr)
                        # Name the actual difference. "stale" with no evidence
                        # is unactionable when the committed and regenerated
                        # trees look identical to the committer.
                        try:
                            e1 = {e.get("path") for e in json.loads(d1).get("entries", [])}
                            e2 = {e.get("path") for e in json.loads(d2).get("entries", [])}
                            only1, only2 = sorted(e1 - e2), sorted(e2 - e1)
                            if only1:
                                print(f"    committed-only entries ({len(only1)}): {only1[:8]}", file=sys.stderr)
                            if only2:
                                print(f"    regenerated-only entries ({len(only2)}): {only2[:8]}", file=sys.stderr)
                            if not only1 and not only2:
                                m1 = {e.get("path"): e for e in json.loads(d1).get("entries", [])}
                                m2 = {e.get("path"): e for e in json.loads(d2).get("entries", [])}
                                changed = [p for p in sorted(m1) if m1[p] != m2.get(p)]
                                print(f"    same {len(m1)} entries; content differs in {len(changed)}: {changed[:8]}", file=sys.stderr)
                        except Exception as exc:  # diagnostics must never mask the drift
                            print(f"    (could not diff: {exc})", file=sys.stderr)
                        has_drift = True
                else:
                    print(f"[generate-ai-manifest] Missing manifest file: {output_file}", file=sys.stderr)
                    has_drift = True
            finally:
                if os.path.exists(temp_file):
                    os.remove(temp_file)
        else:
            if output_file.endswith(".gz"):
                generate_gzipped_manifest(target_dir, output_file, recursive)
            else:
                generate_json_manifest(target_dir, output_file, recursive)

    if check_mode and has_drift:
        sys.exit(1)

#!/usr/bin/env python3
import os
import sys
import re
import glob

ROOT = os.environ.get("MIOS_ROOT") or os.path.dirname(
    os.path.dirname(os.path.abspath(__file__)))
sys.path.insert(0, os.path.join(ROOT, "usr/lib/mios"))
try:
    import mios_toml
except ImportError:
    mios_toml = None

try:
    import tomllib
except ModuleNotFoundError:  # py<3.11
    import tomli as tomllib  # type: ignore

def main(argv):
    toml_path = os.environ.get("MIOS_TOML") or os.path.join(ROOT, "usr/share/mios/mios.toml")
    out_dir = os.environ.get("MIOS_PLAN_OUT") or os.path.join(ROOT, "usr/lib/mios/bake/plan.d")

    check = "--check" in argv

    with open(toml_path, "rb") as fh:
        config = tomllib.load(fh)

    build_bake = config.get("build", {}).get("bake", {})
    core = set(build_bake.get("core", []))
    groups = build_bake.get("groups", ["vllm", "sglang", "ai", "infra", "extra"])
    group_members = build_bake.get("group_members", {})
    firstboot_tokens = build_bake.get("firstboot_tokens", [])
    def is_firstboot(img):
        return any(tok and tok in img for tok in firstboot_tokens)

    enabled_map = config.get("quadlets", {}).get("enable", {})

    quadlet_dir = os.path.join(ROOT, "usr/share/containers/systemd")

    def classify(img):
        for g in groups:
            for tok in group_members.get(g, []):
                if tok and tok in img:
                    return g
        return groups[-1] # extra is catch-all

    var_re = re.compile(r"\$\{([A-Za-z0-9_]+):-([^}]*)\}")

    sidecars = (config.get("image") or {}).get("sidecars") or {}

    def _env(var_name):
        v = os.environ.get(var_name)
        return v if v else None

    def resolve_image_val(val):
        if not val:
            return ""
        def repl_fallback(m):
            var_name = m.group(1)
            fallback = m.group(2)
            env_val = _env(var_name)
            if env_val is not None:
                return env_val
            m_s = re.match(r'^MIOS_(.+)_IMAGE$', var_name)
            if m_s:
                sc_val = sidecars.get(m_s.group(1).lower())
                if sc_val:
                    return sc_val
            return fallback
        val = var_re.sub(repl_fallback, val)

        def repl_var(m):
            var_name = m.group(1)
            env_val = _env(var_name)
            if env_val is not None:
                return env_val
            m_s = re.match(r'^MIOS_(.+)_IMAGE$', var_name)
            if m_s:
                sc_val = sidecars.get(m_s.group(1).lower())
                if sc_val:
                    return sc_val
            return m.group(0)
        val = re.sub(r'\$\{([A-Za-z0-9_]+)\}', repl_var, val)
        return val.strip()

    images_to_bake = []

    for q in sorted(glob.glob(os.path.join(quadlet_dir, "*.container")) +
                    glob.glob(os.path.join(quadlet_dir, "*.image"))):
        base_name = os.path.splitext(os.path.basename(q))[0]
        ext = os.path.splitext(q)[1]

        img = None
        try:
            with open(q, "r", encoding="utf-8", errors="replace") as fh:
                for line in fh:
                    s = line.strip()
                    if s.startswith("Image="):
                        img = s[len("Image="):].strip()
                        break
        except OSError:
            continue

        if not img:
            continue

        resolved_img = resolve_image_val(img)
        if not resolved_img or "$" in resolved_img:
            continue

        first = resolved_img.split("/", 1)[0]
        if first == "localhost":
            continue

        is_core = (resolved_img in core)
        if is_core or enabled_map.get(base_name) is not False:
            images_to_bake.append((resolved_img, base_name))

    for core_img in sorted(core):
        if core_img.startswith("localhost/"):
            if not any(img == core_img for img, _ in images_to_bake):
                images_to_bake.append((core_img, "core-localhost"))

    group_lists = {g: [] for g in groups}
    firstboot_images = []
    for img, base_name in images_to_bake:
        if is_firstboot(img):
            if img not in firstboot_images:
                firstboot_images.append(img)
            continue
        g = classify(img)
        if img not in group_lists[g]:
            group_lists[g].append(img)

    errors = []
    for tok in firstboot_tokens:
        if tok and not any(tok in img for img in core):
            errors.append(f"Firstboot token '{tok}' matches no image in core bake list")

    for img in firstboot_images:
        if img not in core:
            errors.append(f"Firstboot image '{img}' is missing from core bake list")

    discovered_non_localhost = {img for img, _ in images_to_bake if not img.startswith("localhost/")}
    core_non_localhost = {img for img in core if not img.startswith("localhost/")}
    missing_from_core = discovered_non_localhost - core_non_localhost
    extra_in_core = core_non_localhost - discovered_non_localhost
    if missing_from_core:
        for img in sorted(missing_from_core):
            errors.append(f"Quadlet image '{img}' is missing from [build.bake].core")
    if extra_in_core:
        for img in sorted(extra_in_core):
            errors.append(f"Core image '{img}' is not referenced by any Quadlet")

    for img in core:
        parts = img.split("/", 1)
        first = parts[0]
        if not ("." in first or ":" in first or first == "localhost"):
            errors.append(f"Core image '{img}' is not fully-qualified (missing registry prefix)")

    for img, base_name in images_to_bake:
        parts = img.split("/", 1)
        first = parts[0]
        if img.startswith("systemd-"):
            continue
        if not ("." in first or ":" in first or first == "localhost"):
            errors.append(f"Referenced image '{img}' in {base_name} is not fully-qualified")

    if errors:
        for err in errors:
            print(f"[bake-plan-gen] VALIDATION ERROR: {err}", file=sys.stderr)
        return 2

    if not check:
        os.makedirs(out_dir, exist_ok=True)
        for f in glob.glob(os.path.join(out_dir, "*.list")):
            try:
                os.remove(f)
            except OSError:
                pass

        sbom_dir = os.environ.get("MIOS_SBOM_DIR") or os.path.join(ROOT, "usr/share/mios/artifacts/sbom")
        os.makedirs(sbom_dir, exist_ok=True)
        sbom_file = os.path.join(sbom_dir, "bound-images.tsv")

        existing_digests = {}
        if os.path.exists(sbom_file):
            try:
                with open(sbom_file, "r", encoding="utf-8") as sfh:
                    for line in sfh:
                        parts = line.strip().split("\t")
                        if len(parts) >= 3 and parts[0] != "image":
                            existing_digests[parts[0]] = parts[1]
            except OSError:
                pass

        seen_images = set()
        with open(sbom_file, "w", encoding="utf-8", newline="\n") as sfh:
            sfh.write("image\tdigest\tgroup\n")
            for base_img, grp in [("localhost/mios-sys:latest", "sys"), ("localhost/mios-cuda:latest", "cuda")]:
                sfh.write(f"{base_img}\t{existing_digests.get(base_img, 'local')}\t{grp}\n")
                seen_images.add(base_img)

            for img, base_name in images_to_bake:
                if img not in seen_images:
                    g = classify(img)
                    digest = existing_digests.get(img, "local")
                    sfh.write(f"{img}\t{digest}\t{g}\n")
                    seen_images.add(img)

        print(f"[bake-plan-gen] wrote {sbom_file}")

    drift_detected = False

    for idx, g in enumerate(groups):
        prefix = f"{idx+1:02d}"
        plan_file = os.path.join(out_dir, f"{prefix}-{g}.list")
        content = "".join(f"{img}\n" for img in group_lists[g])

        if check:
            cur = ""
            if os.path.exists(plan_file):
                with open(plan_file, "r", encoding="utf-8") as fh:
                    cur = fh.read()
            if cur != content:
                print(f"[bake-plan-gen] DRIFT: {plan_file} does not match projected plan", file=sys.stderr)
                drift_detected = True
        else:
            with open(plan_file, "w", encoding="utf-8", newline="\n") as fh:
                fh.write(content)
            print(f"[bake-plan-gen] wrote {plan_file}")

    fb_file = os.path.join(out_dir, "firstboot.list")
    fb_content = "".join(f"{img}\n" for img in firstboot_images)
    if check:
        cur_fb = ""
        if os.path.exists(fb_file):
            with open(fb_file, "r", encoding="utf-8") as fh:
                cur_fb = fh.read()
        if cur_fb != fb_content:
            print(f"[bake-plan-gen] DRIFT: {fb_file} does not match projected plan", file=sys.stderr)
            drift_detected = True
    else:
        with open(fb_file, "w", encoding="utf-8", newline="\n") as fh:
            fh.write(fb_content)
        print(f"[bake-plan-gen] wrote {fb_file}")

    return 1 if drift_detected else 0

if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))

#!/usr/bin/env python3
# AI-hint: Generate systemd capability drop-in files from the mios.toml [blade.requires] SSOT.
# AI-related: usr/share/mios/dropins/blade-*.conf, usr/share/mios/mios.toml, automation/48-mios-dropin-fanout.sh, /etc/mios/blade.d/
import os
import sys

try:
    import tomllib
except ModuleNotFoundError:  # py<3.11
    import tomli as tomllib  # type: ignore

ROOT = os.environ.get("MIOS_ROOT") or os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
TOML = os.environ.get("MIOS_TOML") or os.path.join(ROOT, "usr/share/mios/mios.toml")
DROPINS_DIR = os.path.join(ROOT, "usr/share/mios/dropins")

def build_dropin_content(capability: str) -> str:
    return f"""# AI-hint: GENERATED systemd capability drop-in for MiOS (WS-BLADE). DO NOT EDIT -- regenerate via tools/generate-blade-dropins.py.
[Unit]
ConditionPathExists=/etc/mios/blade.d/{capability}
"""

def main() -> int:
    try:
        with open(TOML, "rb") as f:
            d = tomllib.load(f)
    except Exception as e:
        print(f"[generate-blade-dropins] ERROR: Failed to load {TOML}: {e}", file=sys.stderr)
        return 1

    blade = d.get("blade") or {}
    requires = blade.get("requires") or {}

    unique_caps = set()
    for caps in requires.values():
        if isinstance(caps, list):
            for cap in caps:
                unique_caps.add(str(cap).strip())
        elif isinstance(caps, str):
            unique_caps.add(caps.strip())

    os.makedirs(DROPINS_DIR, exist_ok=True)

    for cap in sorted(unique_caps):
        if not cap:
            continue
        out_path = os.path.join(DROPINS_DIR, f"blade-{cap}.conf")
        content = build_dropin_content(cap)
        with open(out_path, "w", encoding="utf-8", newline="\n") as f:
            f.write(content)
        print(f"[generate-blade-dropins] Wrote {out_path}")

    return 0

if __name__ == "__main__":
    sys.exit(main())

#!/usr/bin/env python3
# AI-hint: Renders etc/cockpit/cockpit.conf from usr/share/mios/mios.toml SSOT
import os, sys

try:
    import tomllib
except ImportError:
    try:
        import tomli as tomllib
    except ImportError:
        tomllib = None

def main():
    root = os.path.abspath(os.path.join(os.path.dirname(__file__), ".."))
    ssot_path = os.path.join(root, "usr/share/mios/mios.toml")
    target_path = os.path.join(root, "etc/cockpit/cockpit.conf")
    check_mode = "--check" in sys.argv

    if not os.path.isfile(ssot_path):
        print(f"Error: SSOT file not found at {ssot_path}", file=sys.stderr)
        sys.exit(1)

    allow_unencrypted = "true"
    login_to = "false"
    idle_timeout = "0"

    if tomllib:
        try:
            with open(ssot_path, "rb") as f:
                data = tomllib.load(f)
            cockpit_cfg = data.get("cockpit", {})
            if "allow_unencrypted" in cockpit_cfg:
                allow_unencrypted = "true" if cockpit_cfg["allow_unencrypted"] else "false"
            if "login_to" in cockpit_cfg:
                login_to = "true" if cockpit_cfg["login_to"] else "false"
            if "idle_timeout" in cockpit_cfg:
                idle_timeout = str(cockpit_cfg["idle_timeout"])
        except Exception:
            pass

    rendered = f"""# Cockpit configuration file
[WebService]
AllowUnencrypted = {allow_unencrypted}
LoginTo = {login_to}

[Session]
IdleTimeout = {idle_timeout}
"""

    if check_mode:
        rel = os.path.relpath(target_path, root)
        if not os.path.isfile(target_path):
            sys.stderr.write(f"[drift] {rel}: MISSING -- SSOT projection absent (ssot=usr/share/mios/mios.toml [cockpit])\n")
            sys.exit(1)
        with open(target_path, "r", encoding="utf-8") as f:
            current = f.read()
        if current.strip() != rendered.strip():
            import difflib
            sys.stderr.write(f"[drift] {rel}: OUT-OF-SYNC vs mios.toml [cockpit]\n")
            for _l in difflib.unified_diff(current.splitlines(), rendered.splitlines(),
                                           fromfile=f"actual:{rel}", tofile="expected:mios.toml[cockpit]", lineterm=""):
                sys.stderr.write(f"[drift] {_l}\n")
            sys.stderr.write(f"[drift] repro: python3 tools/{os.path.basename(__file__)} --check\n")
            sys.exit(1)
        print("[OK] etc/cockpit/cockpit.conf is in sync with SSOT")
        sys.exit(0)

    os.makedirs(os.path.dirname(target_path), exist_ok=True)
    with open(target_path, "w", encoding="utf-8") as f:
        f.write(rendered)
    print(f"Generated {target_path}")

if __name__ == "__main__":
    main()

#!/usr/bin/env python3
# AI-hint: Renders usr/lib/containers/policy.json from usr/share/mios/mios.toml [security.sigstore] SSOT
import os, sys, json

try:
    import tomllib
except ImportError:
    try:
        import tomli as tomllib
    except ImportError:
        tomllib = None

def main():
    root = os.path.abspath(os.path.join(os.path.dirname(__file__), ".."))
    ssot_path = os.path.join(root, "usr/share/mios/mios.toml")
    target_path = os.path.join(root, "usr/lib/containers/policy.json")
    check_mode = "--check" in sys.argv

    policy_mode = "insecureAcceptEverything"

    if tomllib and os.path.isfile(ssot_path):
        try:
            with open(ssot_path, "rb") as f:
                data = tomllib.load(f)
            sigstore = data.get("security", {}).get("sigstore", {})
            policy_mode = sigstore.get("policy_mode", "insecureAcceptEverything")
        except Exception:
            pass

    policy = {
        "default": [
            {
                "type": policy_mode
            }
        ]
    }

    rendered = json.dumps(policy, indent=2) + "\n"

    if check_mode:
        if not os.path.isfile(target_path):
            print(f"Error: {target_path} does not exist", file=sys.stderr)
            sys.exit(1)
        with open(target_path, "r", encoding="utf-8") as f:
            current = f.read()
        try:
            cur_json = json.loads(current)
            ren_json = json.loads(rendered)
            if cur_json != ren_json:
                print(f"Error: {target_path} is out of sync with [security.sigstore] SSOT", file=sys.stderr)
                sys.exit(1)
        except Exception as e:
            print(f"Error comparing json: {e}", file=sys.stderr)
            sys.exit(1)
        print("[OK] usr/lib/containers/policy.json is in sync with SSOT")
        sys.exit(0)

    os.makedirs(os.path.dirname(target_path), exist_ok=True)
    with open(target_path, "w", encoding="utf-8") as f:
        f.write(rendered)
    print(f"Generated {target_path}")

if __name__ == "__main__":
    main()

#!/usr/bin/env python3
# AI-hint: Generate the agent OUTBOUND egress nftables ruleset (#54 zero-trust federation).
# AI-related: usr/share/mios/security, usr/share/mios/mios.toml, usr/lib/systemd/system/mios-agent-pipe.service, tools/generate-k3s-manifests.sh
# AI-functions: agent_user, build_ruleset, main
"""Generate the MiOS agent egress firewall (#54).

Zero-trust federation calls for an OUTBOUND firewall: a compromised or misled
agent must not be able to exfiltrate to arbitrary internet hosts. The correct
layer for that is the OS (nftables), scoped to the agent's uid -- an app-level
hook would be incomplete (httpx clients are constructed ad-hoc throughout the
orchestrator). This emits that ruleset from SSOT; the operator applies it.

It is uid-scoped, so it does not disturb other users: `web_search` keeps working
because the agent reaches searxng over loopback, and searxng (a different uid)
reaches the internet.
"""
from __future__ import annotations

import os
import sys

try:
    import tomllib
except ModuleNotFoundError:  # py<3.11
    import tomli as tomllib  # type: ignore

ROOT = os.environ.get("MIOS_ROOT") or os.path.dirname(
    os.path.dirname(os.path.abspath(__file__)))
TOML = os.environ.get("MIOS_TOML") or os.path.join(ROOT, "usr/share/mios/mios.toml")
OUT = os.environ.get("MIOS_EGRESS_OUT") or os.path.join(
    ROOT, "usr/share/mios/security/egress.nft")
SERVICE = os.path.join(ROOT, "usr/lib/systemd/system/mios-agent-pipe.service")


def agent_user() -> str:
    """The agent-pipe service user (SSOT = its unit's User=); env override; default."""
    u = os.environ.get("MIOS_AGENT_USER")
    if u:
        return u.strip()
    try:
        for ln in open(SERVICE, encoding="utf-8"):
            if ln.startswith("User="):
                return ln.split("=", 1)[1].strip()
    except OSError:
        pass
    return "mios-ai"


def build_ruleset(mode: str, allow: "list[str]", user: str) -> str:
    if mode == "enforce":
        final = '        log prefix "mios-egress-drop " drop'
        note = "ENFORCE: the agent's non-allowed external egress is logged + DROPPED."
    elif mode == "audit":
        final = '        log prefix "mios-egress-audit " accept'
        note = "AUDIT: the agent's external egress is LOGGED then accepted (observe only)."
    else:
        mode = "off"
        final = "        accept   # mode=off -> no-op even if applied"
        note = "OFF: informational ruleset; applying it changes nothing."

    allow_rules = ""
    v4 = sorted(a for a in allow if ":" not in a)
    v6 = sorted(a for a in allow if ":" in a)
    if v4:
        allow_rules += f'        ip daddr {{ {", ".join(v4)} }} accept\n'
    if v6:
        allow_rules += f'        ip6 daddr {{ {", ".join(v6)} }} accept\n'

    return f"""# AI-hint: GENERATED nftables egress firewall for the MiOS agent (#54). DO NOT EDIT -- regenerate via tools/generate-egress-firewall.py. {note}
table inet mios_egress {{
    chain output {{
        type filter hook output priority filter; policy accept;
        meta skuid != "{user}" accept
        oifname "lo" accept
        ip daddr 127.0.0.0/8 accept
        ip6 daddr ::1 accept
        ip daddr 100.64.0.0/10 accept
        ip daddr 172.16.0.0/12 accept
{allow_rules}{final}
    }}
}}
"""


def main() -> int:
    with open(TOML, "rb") as f:
        d = tomllib.load(f)
    eg = ((d.get("security") or {}).get("egress")) or {}
    mode = str(eg.get("mode", "off")).strip().lower()
    allow = [str(a).strip() for a in (eg.get("allow") or []) if str(a).strip()]
    user = agent_user()
    os.makedirs(os.path.dirname(OUT), exist_ok=True)
    with open(OUT, "w", encoding="utf-8", newline="\n") as f:
        f.write(build_ruleset(mode, allow, user))
    print(f"[egress-fw] wrote {OUT} (mode={mode}, user={user}, allow={len(allow)})")
    return 0


if __name__ == "__main__":
    sys.exit(main())

#!/usr/bin/env python3
import os
import sys
import re
import glob

try:
    import tomllib
except ImportError:
    try:
        import tomli as tomllib
    except ImportError:
        print("Error: neither tomllib nor tomli is installed.", file=sys.stderr)
        sys.exit(1)

TARGET_SECTIONS = [
    "ports", "ai", "identity", "locale", "auth", "network", "desktop", 
    "branding", "image", "bootstrap", "profile", "colors", "observability", 
    "sandbox", "security", "code_mode", "hermes", "routing", "agents", "a2a",
    "power", "mini"
]

SHORT_ALIAS_PREFIX = {
    "ai.vllm":   "MIOS_VLLM",
    "ai.sglang": "MIOS_SGLANG",
}
SHORT_ALIAS_IRREGULAR = {
    "ai.vllm.v1_engine":            "MIOS_VLLM_USE_V1",
    "ai.sglang.unified_radix_tree": "MIOS_SGLANG_ENABLE_UNIFIED_RADIX_TREE",
    "ai.sglang.hierarchical_cache": "MIOS_SGLANG_ENABLE_HIERARCHICAL_CACHE",
}

def _alias_for(path):
    a = SHORT_ALIAS_IRREGULAR.get(path)
    if a is not None:
        return a
    for pfx, rep in SHORT_ALIAS_PREFIX.items():
        if path.startswith(pfx + "."):
            return rep + path[len(pfx):].upper().replace(".", "_").replace("-", "_").replace("/", "_")
    return None

def walk(d, prefix=""):
    results = []
    if not isinstance(d, dict):
        return results

    for k, v in d.items():
        path = f"{prefix}.{k}" if prefix else k

        if path == "routing.domains":
            continue

        if isinstance(v, dict):
            results.extend(walk(v, path))
        else:
            alias = _alias_for(path)
            env_name = alias if alias else "MIOS_" + path.upper().replace(".", "_").replace("-", "_").replace("/", "_")
            results.append((path, env_name))
    return results

def generate_referenced_vars(root):
    emitter_suffixes = (
        "usr/lib/mios/userenv.sh", "tools/lib/userenv.sh",
        "usr/libexec/mios/system-sync-env.sh",
        "usr/share/mios/names.generated.txt",
        "usr/share/doc/mios/reference/naming-unification.md",
        # Generated in full by tools/render-globals.py -- they DEFINE the whole
        # namespace, they do not consume it. Scanning them makes the registry
        # circular: every emitted name would count as a reference to itself.
        "automation/lib/globals.sh", "automation/lib/globals.ps1",
        # ...and so are the renderers themselves: their prose carries example
        # placeholders (${MIOS_PORT_X:-N}) that are not real variables.
        "tools/render-globals.py", "tools/render-ports.py",
    )
    var_re = re.compile(r"MIOS_[A-Z0-9_]+")
    consumer_globs = ("*.container", "*.service", "*.timer", "*.py", "*.sh", "*.toml",
                      "*.ps1", "*.psm1", "*.yaml", "*.yml", "Justfile", ".env.mios", "*.tmpl",
                      "Containerfile", "Containerfile.*", "*.nft", "*.sql")

    refs = set()
    import subprocess
    tracked_files = []
    try:
        res = subprocess.run(["git", "ls-files"], capture_output=True, text=True, check=True, cwd=root)
        tracked_files = [os.path.join(root, f) for f in res.stdout.splitlines() if os.path.isfile(os.path.join(root, f))]
    except Exception:
        tracked_files = []
        for r, _d, files in os.walk(root):
            rel_r = os.path.relpath(r, root).replace("\\", "/")
            parts = rel_r.split('/')
            if any(p in parts for p in ('tmp', '.git', '.venv', '__pycache__', 'node_modules', 'dist', 'build', '.system_generated', 'scratch', 'logs', 'bib-configs', 'medicat_stage', 'isobuild', 'isobuild_live', 'isobuild2')):
                continue
            for f in files:
                tracked_files.append(os.path.join(r, f))

    if tracked_files:
        for path in tracked_files:
            rel = os.path.relpath(path, root).replace("\\", "/")
            fn = os.path.basename(path)
            if any(rel.endswith(s) for s in emitter_suffixes):
                continue
            if not any(glob.fnmatch.fnmatch(fn, g) for g in consumer_globs):
                continue
            try:
                with open(path, encoding="utf-8", errors="ignore") as fh:
                    for line in fh:
                        for m in var_re.finditer(line):
                            v = m.group(0).rstrip("_")
                            if not v or v == "MIOS":
                                continue
                            if re.match(rf"\s*(export\s+)?{v}=", line):
                                continue
                            refs.add(v)
            except (OSError, UnicodeError):
                continue
    else:
        for dirpath, _dirs, files in os.walk(root):
            if "/.git" in dirpath.replace("\\", "/"):
                continue
            for fn in files:
                path = os.path.join(dirpath, fn)
                rel = os.path.relpath(path, root).replace("\\", "/")
                if any(rel.endswith(s) for s in emitter_suffixes):
                    continue
                if not any(glob.fnmatch.fnmatch(fn, g) for g in consumer_globs):
                    continue
                try:
                    with open(path, encoding="utf-8", errors="ignore") as fh:
                        for line in fh:
                            for m in var_re.finditer(line):
                                v = m.group(0).rstrip("_")
                                if not v or v == "MIOS":
                                    continue
                                if re.match(rf"\s*(export\s+)?{v}=", line):
                                    continue
                                refs.add(v)
                except (OSError, UnicodeError):
                    continue

    ref_file = os.path.join(root, "usr/share/mios/referenced_names.txt")
    os.makedirs(os.path.dirname(ref_file), exist_ok=True)
    with open(ref_file, "w", encoding="utf-8", newline="\n") as f:
        for r in sorted(refs):
            f.write(f"{r}\n")

def main():
    root = os.environ.get("MIOS_DRIFT_ROOT") or os.getcwd()
    toml_path = os.path.join(root, "usr/share/mios/mios.toml")
    if not os.path.isfile(toml_path):
        if os.path.isfile("usr/share/mios/mios.toml"):
            toml_path = "usr/share/mios/mios.toml"
        else:
            print(f"Error: mios.toml not found at {toml_path}", file=sys.stderr)
            return 1

    with open(toml_path, "rb") as fh:
        data = tomllib.load(fh)

    all_pairs = []
    for sec in TARGET_SECTIONS:
        if sec in data:
            all_pairs.extend(walk(data[sec], sec))

    names_file = os.path.join(root, "usr/share/mios/names.generated.txt")
    os.makedirs(os.path.dirname(names_file), exist_ok=True)
    with open(names_file, "w", encoding="utf-8", newline="\n") as f:
        for path, env_name in all_pairs:
            f.write(f"{path}  {env_name}\n")
            print(f"{path}  {env_name}")

    generate_referenced_vars(root)
    return 0

if __name__ == "__main__":
    sys.exit(main())

#!/usr/bin/env python3
# AI-hint: Generate .pod Quadlets from the mios.toml [pods.*] co-resident groups (WS-7 pods-as-SSOT). Renders usr/share/containers/systemd/<name>.pod deterministically from each [pods.<name>] (description/network/after/wants/wanted_by/members/doc) so a co-resident container group is declared ONCE in SSOT and the Quadlet can't drift; tools/generate-k3s-manifests.sh then projects the live pods to k3s. --check (drift gate) compares without writing; --selftest asserts the pure renderer offline.
# AI-related: usr/share/mios/mios.toml, usr/share/containers/systemd, tools/generate-k3s-manifests.sh, automation/98-drift-checks.sh, automation/34-render-quadlets.sh
# AI-functions: render_pod_quadlet, _wrap_doc, load_pods, main, _selftest
"""Generate MiOS .pod Quadlets from the [pods.*] SSOT (WS-7).

A co-resident group -- a set of containers that must share a podman pod (one
network namespace + lifecycle) -- was previously a hand-authored .pod Quadlet
(only mios-webtools). That is drift-prone: the pod's [Unit]/[Pod]/[Install] and
its member list lived only in the file. This projects each [pods.<name>] in
mios.toml to a deterministic <name>.pod under usr/share/containers/systemd/, so:

  * the co-resident group is declared ONCE (SSOT), and
  * tools/generate-k3s-manifests.sh -- which reads the LIVE pods -- projects the
    same workloads to k3s, so the cluster path is one faithful bridge from SSOT.

Each member .container still declares `Pod=<name>.pod` (Quadlet wires the
Wants/After on the pod service); the member list here is the documented SSOT +
fuels a drift check that every declared member exists as a .container.

Pure renderer (render_pod_quadlet) so it unit-tests offline (--selftest), in the
sibling style of the other tools/ generators. Same SSOT -> byte-identical output.
"""
from __future__ import annotations

import os
import sys
import re

_SIDECARS: dict = {}

def _sidecar_image(var_name: str):
    """Digest-pinned image for a MIOS_<X>_IMAGE var from [image.sidecars] (the
    digest SSOT), used when the env isn't sourced so bare regeneration renders
    the SAME @sha256 as a build-time render (fixes Quadlet digest clobber).
    Returns None for non-image vars or sidecars not in SSOT (keeps literal
    fallback behaviour for locally-built images like MIOS_FIRECRAWL_IMAGE)."""
    m = re.match(r'^MIOS_(.+)_IMAGE$', var_name)
    if not m:
        return None
    val = _SIDECARS.get(m.group(1).lower())
    return val if isinstance(val, str) and val else None

_PLACEHOLDER_VARS: set[str] = {"FEDORA_VERSION", "MIOS_VERSION"}

def load_placeholders(toml_path: str) -> set[str]:
    try:
        with open(toml_path, "rb") as f:
            d = tomllib.load(f)
        phs = (d.get("generator") or {}).get("placeholders") or []
        return set(phs) | {"FEDORA_VERSION", "MIOS_VERSION"}
    except Exception:
        return {"FEDORA_VERSION", "MIOS_VERSION"}

def resolve_env_vars(val: str | bool | list | dict) -> str | bool | list | dict:
    if isinstance(val, list):
        return [resolve_env_vars(x) for x in val]
    if isinstance(val, dict):
        return {k: resolve_env_vars(v) for k, v in val.items()}
    if not isinstance(val, str):
        return val

    def _env(var_name: str):
        v = os.environ.get(var_name)
        return v if v else None

    def repl_fallback(m):
        var_name = m.group(1)
        fallback = m.group(2)
        if var_name.startswith("MIOS_PORT_") or var_name in _PLACEHOLDER_VARS or var_name.endswith("_VERSION"):
            return m.group(0)
        env_val = _env(var_name)
        if env_val is not None:
            return env_val
        pinned = _sidecar_image(var_name)
        if pinned is not None:
            return pinned
        return fallback
    val = re.sub(r'\$\{([A-Za-z0-9_]+):-([^}]*)\}', repl_fallback, val)

    def repl_var(m):
        var_name = m.group(1)
        if var_name.startswith("MIOS_PORT_") or var_name in _PLACEHOLDER_VARS or var_name.endswith("_VERSION"):
            return m.group(0)
        env_val = _env(var_name)
        if env_val is not None:
            return env_val
        pinned = _sidecar_image(var_name)
        if pinned is not None:
            return pinned
        return m.group(0)
    val = re.sub(r'\$\{([A-Za-z0-9_]+)\}', repl_var, val)

    return val

try:
    import tomllib
except ModuleNotFoundError:  # py<3.11
    import tomli as tomllib  # type: ignore

ROOT = os.environ.get("MIOS_ROOT") or os.path.dirname(
    os.path.dirname(os.path.abspath(__file__)))
TOML = os.environ.get("MIOS_TOML") or os.path.join(ROOT, "usr/share/mios/mios.toml")
OUT_DIR = os.environ.get("MIOS_POD_OUT") or os.path.join(
    ROOT, "usr/share/containers/systemd")

# The preserve-as-placeholder var set is operator-defined in [generator].
# Resolve it here (TOML is known) rather than leaving the renderer hardcoded.
_PLACEHOLDER_VARS = load_placeholders(TOML)


def _wrap_doc(doc: str, width: int = 76) -> "list[str]":
    """Wrap the SSOT `doc` prose into `# `-prefixed comment lines (deterministic,
    greedy word wrap) so the rationale rides in the generated Quadlet."""
    out: list[str] = []
    for para in str(doc or "").split("\n"):
        words = para.split()
        if not words:
            out.append("#")
            continue
        line = "#"
        for w in words:
            if len(line) + 1 + len(w) > width and line != "#":
                out.append(line)
                line = "# " + w
            else:
                line = (line + " " + w) if line != "#" else "# " + w
        out.append(line)
    return out


def _resolve_port(port_str: str, ports: dict) -> str:
    parts = port_str.split(":")
    resolved_parts = []
    for p in parts:
        p_clean = p.strip()
        if p_clean.startswith("${") and p_clean.endswith("}"):
            p_clean = p_clean[2:-1]
            if p_clean.startswith("ports."):
                p_clean = p_clean[6:]
        if p_clean in ports:
            resolved_parts.append(str(ports[p_clean]))
        else:
            resolved_parts.append(p)
    return ":".join(resolved_parts)


def render_pod_quadlet(name: str, spec: dict, ports: dict | None = None) -> str:
    """Render the .pod Quadlet text for one [pods.<name>] spec. Deterministic:
    sorted nothing (preserve declared order), fixed section order. PodName is the
    pod `name` with any leading 'mios-' kept (the unit is <name>.pod -> Quadlet
    derives <name>-pod.service)."""
    desc = resolve_env_vars(str(spec.get("description") or f"MiOS {name} pod"))
    network = resolve_env_vars(str(spec.get("network") or "host"))
    after = [resolve_env_vars(str(x)) for x in (spec.get("after") or [])]
    wants = [resolve_env_vars(str(x)) for x in (spec.get("wants") or [])]
    wanted_by = [resolve_env_vars(str(x)) for x in (spec.get("wanted_by") or ["multi-user.target"])]
    publish_ports = [resolve_env_vars(str(x)) for x in (spec.get("publish_ports") or [])]
    if ports:
        publish_ports = [_resolve_port(p, ports) for p in publish_ports]
    members = [str(x).split("#", 1)[0].strip() for x in (spec.get("members") or [])]
    members = [m for m in members if m]

    lines: list[str] = []
    lines.append(
        f"# AI-hint: GENERATED Quadlet pod for the co-resident group '{name}' "
        f"(WS-7 pods-as-SSOT). DO NOT EDIT -- regenerate via "
        f"tools/generate-pod-quadlets.py from [pods.{name}] in mios.toml. "
        f"Members ({len(members)}): {', '.join(members)}.")
    lines.append(
        f"# AI-related: usr/share/mios/mios.toml, tools/generate-pod-quadlets.py, "
        + ", ".join(f"{m}.container" for m in members))
    lines.append(f"# /usr/share/containers/systemd/{name}.pod")
    if spec.get("doc"):
        lines.extend(_wrap_doc(spec["doc"]))
    if members:
        lines.append("# Members (each member .container declares Pod="
                     f"{name}.pod):")
        for m in members:
            lines.append(f"#   {m}")
    lines.append("[Unit]")
    lines.append(f"Description={desc}")
    if after:
        lines.append("After=" + " ".join(after))
    if wants:
        lines.append("Wants=" + " ".join(wants))
    lines.append("")
    lines.append("[Pod]")
    lines.append(f"PodName={name}")
    lines.append(f"Network={network}")
    for port in publish_ports:
        lines.append(f"PublishPort={port}")
    lines.append("")
    lines.append("[Install]")
    lines.append("WantedBy=" + " ".join(wanted_by))
    return "\n".join(lines) + "\n"


def load_pods(toml_path: str) -> dict:
    with open(toml_path, "rb") as f:
        d = tomllib.load(f)
    return d.get("pods") or {}


def load_ports(toml_path: str) -> dict:
    with open(toml_path, "rb") as f:
        d = tomllib.load(f)
    return d.get("ports") or {}


def load_sidecars(toml_path: str) -> dict:
    """[image.sidecars] -- the digest-pinned image SSOT. Consulted by
    _sidecar_image() so bare (no-userenv) regeneration renders the committed
    @sha256 instead of the digestless inline fallback (Quadlet digest drift)."""
    with open(toml_path, "rb") as f:
        d = tomllib.load(f)
    return (d.get("image") or {}).get("sidecars") or {}


def load_containers(toml_path: str) -> dict:
    with open(toml_path, "rb") as f:
        d = tomllib.load(f)
    return d.get("containers") or {}


def load_networks(toml_path: str) -> dict:
    with open(toml_path, "rb") as f:
        d = tomllib.load(f)
    return d.get("networks") or d.get("network") or {}


def load_volumes(toml_path: str) -> dict:
    with open(toml_path, "rb") as f:
        d = tomllib.load(f)
    return d.get("volumes") or d.get("volume") or {}


def load_enabled_quadlets(toml_path: str) -> dict:
    with open(toml_path, "rb") as f:
        d = tomllib.load(f)
    return d.get("quadlets", {}).get("enable", {})


def render_nested_quadlet(name: str, spec: dict, unit_type: str) -> str:
    lines: list[str] = []
    lines.append(
        f"# AI-hint: GENERATED Quadlet {unit_type} '{name}' "
        f"(WS-7 pods-as-SSOT). DO NOT EDIT -- regenerate via "
        f"tools/generate-pod-quadlets.py from [{unit_type}s.{name}] in mios.toml."
    )
    lines.append(f"# /usr/share/containers/systemd/{name}.{unit_type}")
    if name == "mios-llm-heavy-alt" and unit_type == "container":
        lines.append("# DEPRECATED (Part 10): retire by setting [converge.inference].retire_heavy_alt = true and running the migration guide at usr/share/doc/mios/guides/inference-consolidation.md.")

    main_section = unit_type.capitalize()

    def section_key(sec_name: str):
        if sec_name.lower() == "unit":
            return (0, sec_name)
        elif sec_name.lower() == main_section.lower():
            return (1, sec_name)
        elif sec_name.lower() == "install":
            return (2, sec_name)
        else:
            return (3, sec_name)

    for sec in sorted(spec.keys(), key=section_key):
        sec_data = spec[sec]
        if not isinstance(sec_data, dict):
            continue
        lines.append("")
        lines.append(f"[{sec}]")
        for k in sorted(sec_data.keys()):
            val = sec_data[k]
            if isinstance(val, list):
                for item in val:
                    resolved_item = resolve_env_vars(item)
                    lines.append(f"{k}={resolved_item}")
            elif isinstance(val, bool):
                lines.append(f"{k}={'true' if val else 'false'}")
            else:
                resolved_val = resolve_env_vars(val)
                if k == "Image" and resolved_val == "":
                    continue
                if k in ("User", "Group") and resolved_val == "":
                    continue
                lines.append(f"{k}={resolved_val}")


    return "\n".join(lines).strip() + "\n"


def main(argv: "list[str]") -> int:
    if "--selftest" in argv:
        return _selftest()
    check = "--check" in argv
    global _SIDECARS
    _SIDECARS = load_sidecars(TOML)
    enabled_map = load_enabled_quadlets(TOML)
    pods = load_pods(TOML)
    ports = load_ports(TOML)
    containers = load_containers(TOML)
    networks = load_networks(TOML)
    volumes = load_volumes(TOML)

    for name in enabled_map:
        if name not in containers:
            print(f"[pod-gen] ERROR: key '{name}' in [quadlets.enable] does not map to any container in [containers]", file=sys.stderr)
            return 1

    if not pods and not containers and not networks and not volumes:
        print("[pod-gen] no Quadlets in SSOT -- nothing to do")
        return 0

    for pod_name, pod_spec in pods.items():
        if "members" in pod_spec:
            filtered_members = []
            for m in pod_spec["members"]:
                m_name = str(m).split("#", 1)[0].strip()
                if enabled_map.get(m_name) is not False:
                    filtered_members.append(m)
            pod_spec["members"] = filtered_members

    os.makedirs(OUT_DIR, exist_ok=True)
    drift = 0
    wrote = 0
    member_miss = 0
    active_units = 0

    for name in sorted(pods):
        spec = pods[name]
        if not isinstance(spec, dict):
            continue
        text = render_pod_quadlet(name, spec, ports)
        out = os.path.join(OUT_DIR, f"{name}.pod")
        for m in [str(x).split("#", 1)[0].strip() for x in (spec.get("members") or [])]:
            if m and not os.path.exists(os.path.join(OUT_DIR, f"{m}.container")):
                print(f"[pod-gen] WARN {name}: member {m}.container missing", file=sys.stderr)
                member_miss += 1
        active_units += 1
        if check:
            cur = ""
            if os.path.exists(out):
                with open(out, encoding="utf-8") as f:
                    cur = f.read()
            if cur != text:
                print(f"[pod-gen] DRIFT {out} (regenerate via tools/generate-pod-quadlets.py)",
                      file=sys.stderr)
                drift += 1
            continue
        with open(out, "w", encoding="utf-8", newline="\n") as f:
            f.write(text)
        wrote += 1
        print(f"[pod-gen]   wrote {out}")

    categories = [
        (containers, "container"),
        (networks, "network"),
        (volumes, "volume")
    ]

    for specs, unit_type in categories:
        for name in sorted(specs):
            spec = specs[name]
            if not isinstance(spec, dict):
                continue

            if unit_type == "container" and enabled_map.get(name) is False:
                out = os.path.join(OUT_DIR, f"{name}.{unit_type}")
                if check:
                    if os.path.exists(out):
                        print(f"[pod-gen] DRIFT {out} should not exist (disabled in SSOT)", file=sys.stderr)
                        drift += 1
                else:
                    if os.path.exists(out):
                        os.remove(out)
                        print(f"[pod-gen]   removed disabled {out}")
                continue

            text = render_nested_quadlet(name, spec, unit_type)
            out = os.path.join(OUT_DIR, f"{name}.{unit_type}")
            active_units += 1
            if check:
                cur = ""
                if os.path.exists(out):
                    with open(out, encoding="utf-8") as f:
                        cur = f.read()
                if cur != text:
                    print(f"[pod-gen] DRIFT {out} (regenerate via tools/generate-pod-quadlets.py)",
                          file=sys.stderr)
                    drift += 1
                continue
            with open(out, "w", encoding="utf-8", newline="\n") as f:
                f.write(text)
            wrote += 1
            print(f"[pod-gen]   wrote {out}")

    if check:
        if drift:
            print(f"[pod-gen] {drift} Quadlet unit(s) DRIFTED from SSOT", file=sys.stderr)
            return 1
        print(f"[pod-gen] all {active_units} Quadlet unit(s) match SSOT")
        return 1 if member_miss else 0

    print(f"[pod-gen] wrote {wrote} Quadlet unit(s) to {OUT_DIR}")
    return 0


def _selftest() -> int:
    fails = 0

    def ck(name, cond):
        nonlocal fails
        if not cond:
            fails += 1
        print(f"[{'PASS' if cond else 'FAIL'}] {name}")

    spec = {
        "description": "test pod",
        "network": "host",
        "after": ["network-online.target", "x.service"],
        "wants": ["network-online.target"],
        "wanted_by": ["multi-user.target", "default.target"],
        "publish_ports": ["8080:8080", "${ports.open_webui}:8080", "searxng:80"],
        "members": ["mios-a", "mios-b  # comment"],
        "doc": "Line one rationale that is reasonably long so wrapping engages across the width boundary deterministically.",
    }
    mock_ports = {"open_webui": 8033, "searxng": 8899}
    t = render_pod_quadlet("mios-test", spec, mock_ports)
    ck("selftest: has [Pod] section", "[Pod]" in t)
    ck("selftest: PodName from name", "PodName=mios-test" in t)
    ck("selftest: Network rendered", "Network=host" in t)
    ck("selftest: PublishPort literal rendered", "PublishPort=8080:8080" in t)
    ck("selftest: PublishPort resolved placeholder", "PublishPort=8033:8080" in t)
    ck("selftest: PublishPort resolved raw name", "PublishPort=8899:80" in t)
    ck("selftest: After joined", "After=network-online.target x.service" in t)
    ck("selftest: Wants joined", "Wants=network-online.target" in t)
    ck("selftest: WantedBy joined", "WantedBy=multi-user.target default.target" in t)
    ck("selftest: member comment stripped", "mios-b.container" in t and "# comment" not in t.split("AI-related")[1].split("\n")[0])
    ck("selftest: doc wrapped as comments", "# Line one rationale" in t)
    ck("selftest: deterministic", render_pod_quadlet("mios-test", spec, mock_ports) == t)
    ck("selftest: trailing newline", t.endswith("\n"))

    container_spec = {
        "Unit": {
            "Description": "Test container unit",
            "After": "network-online.target"
        },
        "Container": {
            "Image": "docker.io/library/alpine:latest",
            "ContainerName": "test-alpine",
            "Environment": ["A=1", "B=2"]
        }
    }
    tc = render_nested_quadlet("test", container_spec, "container")
    ck("selftest nested: has [Unit] section", "[Unit]" in tc)
    ck("selftest nested: has [Container] section", "[Container]" in tc)
    ck("selftest nested: has Environment entries", "Environment=A=1" in tc and "Environment=B=2" in tc)
    ck("selftest nested: Unit section before Container", tc.index("[Unit]") < tc.index("[Container]"))
    ck("selftest nested: trailing newline", tc.endswith("\n"))

    global _SIDECARS
    _SIDECARS = {"pgvector": "docker.io/pgvector/pgvector:0.8.3-pg17@sha256:deadbeef"}
    os.environ.pop("MIOS_PGVECTOR_IMAGE", None)
    img_spec = {"Container": {"Image": "${MIOS_PGVECTOR_IMAGE:-docker.io/pgvector/pgvector:0.8.3-pg17}"}}
    ic = render_nested_quadlet("mios-pgvector", img_spec, "container")
    ck("selftest: bare-env resolves digest from [image.sidecars]", "@sha256:deadbeef" in ic)

    priv_spec = {"Container": {
        "Image": "${MIOS_PGVECTOR_IMAGE:-docker.io/pgvector/pgvector:0.8.3-pg17}",
        "User": "${MIOS_GUACD_UID:-811}",
        "Group": "${MIOS_GUACD_GID:-811}",
    }}
    for _v in ("MIOS_GUACD_UID", "MIOS_GUACD_GID", "MIOS_PGVECTOR_IMAGE"):
        os.environ[_v] = ""
    pc = render_nested_quadlet("mios-guacd", priv_spec, "container")
    for _v in ("MIOS_GUACD_UID", "MIOS_GUACD_GID", "MIOS_PGVECTOR_IMAGE"):
        os.environ.pop(_v, None)
    ck("selftest: empty env var falls back to inline default (User=)", "User=811" in pc)
    ck("selftest: empty env var falls back to inline default (Group=)", "Group=811" in pc)
    ck("selftest: empty env var still resolves the sidecar digest", "@sha256:deadbeef" in pc)
    ck("selftest: empty-env render == bare-env render",
       pc == render_nested_quadlet("mios-guacd", priv_spec, "container"))
    _SIDECARS = {}

    print(f"\n{'ok' if fails == 0 else str(fails) + ' FAILED'}")
    return 1 if fails else 0



if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))

#!/usr/bin/env python3
# AI-hint: Flattens usr/lib/bootc/kargs.d/*.toml drop-ins into usr/lib/kernel/cmdline SSOT
import os, sys, glob

try:
    import tomllib
except ImportError:
    try:
        import tomli as tomllib
    except ImportError:
        tomllib = None

def main():
    root = os.path.abspath(os.path.join(os.path.dirname(__file__), ".."))
    kargs_dir = os.path.join(root, "usr/lib/bootc/kargs.d")
    target_path = os.path.join(root, "usr/lib/kernel/cmdline")
    check_mode = "--check" in sys.argv

    if not tomllib:
        print("Error: tomllib unavailable", file=sys.stderr)
        sys.exit(1)

    kargs = []
    for f in sorted(glob.glob(os.path.join(kargs_dir, "*.toml"))):
        try:
            with open(f, "rb") as fp:
                d = tomllib.load(fp)
                if "kargs" in d and isinstance(d["kargs"], list):
                    kargs.extend(d["kargs"])
        except Exception as e:
            print(f"Error parsing {f}: {e}", file=sys.stderr)

    rendered = " ".join(kargs).strip() + "\n"

    if check_mode:
        rel = os.path.relpath(target_path, root)
        if not os.path.isfile(target_path):
            sys.stderr.write(f"[drift] {rel}: MISSING -- SSOT projection absent (ssot=usr/lib/bootc/kargs.d/*.toml)\n")
            sys.exit(1)
        with open(target_path, "r", encoding="utf-8") as f:
            current = f.read()
        if current.strip() != rendered.strip():
            import difflib
            sys.stderr.write(f"[drift] {rel}: OUT-OF-SYNC vs usr/lib/bootc/kargs.d/*.toml\n")
            for _l in difflib.unified_diff(current.splitlines(), rendered.splitlines(),
                                           fromfile=f"actual:{rel}", tofile="expected:kargs.d/*.toml", lineterm=""):
                sys.stderr.write(f"[drift] {_l}\n")
            sys.stderr.write(f"[drift] repro: python3 tools/{os.path.basename(__file__)} --check\n")
            sys.exit(1)
        print("[OK] usr/lib/kernel/cmdline is in sync with kargs.d/*.toml")
        sys.exit(0)

    os.makedirs(os.path.dirname(target_path), exist_ok=True)
    with open(target_path, "w", encoding="utf-8") as f:
        f.write(rendered)
    print(f"Generated {target_path}")

if __name__ == "__main__":
    main()

# AI-hint: Parses codebase files to extract metadata, redact secrets, and compile a compressed `repo-rag-snapshot.json.gz` file to provide a unified semantic knowledge base for RAG-based AI agents.
# AI-functions: redact_secrets, parse_metadata, generate_unified_knowledge
import os
import json
import re
import gzip
from datetime import datetime

def redact_secrets(content):
    """Redacts common secret patterns from content."""
    patterns = [
        (r'(?i)(api_key|secret|password|token|private_key)(\s*[:=]\s*)([^\s,]+)', r'\1\2[REDACTED]'),
        (r'AIza[0-9A-Za-z-_]{35}', '[REDACTED]'),  # Cloud API Keys
        (r'sk-[0-9A-Za-z]{48}', '[REDACTED]'),      # OpenAI Keys
    ]
    redacted = content
    for pattern, replacement in patterns:
        redacted = re.sub(pattern, replacement, redacted)
    return redacted

def parse_metadata(content, file_path):
    """Extracts structured metadata and patterns from content."""
    meta = {
        "title": os.path.basename(file_path),
        "summary": "",
        "patterns": [],
        "technologies": [],
        "logic_type": "unknown"
    }

    title_match = re.search(r'^#\s+(.+)$', content, re.MULTILINE)
    if title_match:
        meta["title"] = title_match.group(1).strip()

    kb_match = re.search(r'```json:knowledge\s*\n(.*?)\n```', content, re.DOTALL)
    if kb_match:
        try:
            kb = json.loads(kb_match.group(1))
            meta.update(kb)
        except json.JSONDecodeError:
            pass

    tech_keywords = ["bootc", "podman", "quadlet", "k3s", "ceph", "nvidia", "gnome", "selinux", "greenboot", "composefs"]
    for tech in tech_keywords:
        if tech in content.lower():
            meta["technologies"].append(tech)

    return meta

def generate_unified_knowledge(output_file="artifacts/repo-rag-snapshot.json.gz"):
    print(f" Flattening Historical Knowledge into UKB: {output_file}...")

    ignore_dirs = {".git", ".venv", "__pycache__", "node_modules", "artifacts"}
    snapshot = {
        "metadata": {
            "project": "MiOS",
            "timestamp": datetime.now().isoformat(),
            "scope": "Flattened Historical & Semantic Knowledge",
            "rag_format_version": "2.0",
            "foss_compliant": True,
            "ai_native": True
        },
        "semantic_index": {
            "core_blueprints": [],
            "engineering_patterns": [],
            "historical_context": [],
            "automation_logic": [],
            "validation_suites": []
        },
        "knowledge_nodes": []
    }

    for root, dirs, files in os.walk("."):
        dirs[:] = [d for d in dirs if d not in ignore_dirs]

        for file in files:
            file_path = os.path.join(root, file)
            rel_path = os.path.relpath(file_path, start=os.getcwd())

            if not file.endswith((".md", ".json", ".sh", ".py", ".ps1", ".toml", ".yaml", ".yml", ".conf", ".txt", ".log", "Containerfile", "Justfile")) and not file.startswith("."):
                continue

            if os.path.getsize(file_path) > 1024 * 1024:
                continue

            try:
                with open(file_path, 'r', encoding='utf-8', errors='ignore') as f:
                    content = f.read()

                content = redact_secrets(content)
                meta = parse_metadata(content, rel_path)

                category = "other"
                index_key = None

                if rel_path.startswith("specs/core/"): 
                    category = "core_foundation"
                    index_key = "core_blueprints"
                elif rel_path.startswith("specs/engineering/"): 
                    category = "engineering"
                    index_key = "engineering_patterns"
                elif rel_path.startswith("specs/memory/") or rel_path.startswith("specs/changelogs/") or rel_path.startswith("specs/audit/"):
                    category = "history"
                    index_key = "historical_context"
                elif rel_path.startswith("automation/"): 
                    category = "automation"
                    index_key = "automation_logic"
                elif rel_path.startswith("evals/"): 
                    category = "validation"
                    index_key = "validation_suites"
                elif rel_path.startswith("specs/knowledge/"):
                    category = "research"
                    index_key = "engineering_patterns"

                node = {
                    "path": rel_path,
                    "category": category,
                    "metadata": meta,
                    "content": content
                }

                snapshot["knowledge_nodes"].append(node)
                if index_key:
                    snapshot["semantic_index"][index_key].append({
                        "path": rel_path,
                        "title": meta["title"],
                        "technologies": meta["technologies"]
                    })

            except Exception as e:
                print(f"[!] Could not process {rel_path}: {e}")

    os.makedirs(os.path.dirname(output_file), exist_ok=True)

    with gzip.open(output_file, 'wt', encoding='utf-8') as f:
        json.dump(snapshot, f, indent=2)

    print(f"[ok] Flattened UKB generated with {len(snapshot['knowledge_nodes'])} semantic nodes.")

if __name__ == "__main__":
    generate_unified_knowledge()

#!/usr/bin/env python3
# AI-hint: Drift check helper for verifying surface parity and one-way imports.
"""AST-based drift check helper for mios_pipe module surface parity."""

from __future__ import annotations

import ast
import os
import sys

AGENT_PIPE_DIR = os.path.join("usr", "lib", "mios", "agent-pipe")
MIOS_PIPE_DIR = os.path.join(AGENT_PIPE_DIR, "mios_pipe")
SERVER_PY = os.path.join(AGENT_PIPE_DIR, "server.py")


def check_one_way_imports() -> list[str]:
    """Ensure no file in mios_pipe/ imports server."""
    offenders = []
    if not os.path.exists(MIOS_PIPE_DIR):
        return offenders

    for root, _, files in os.walk(MIOS_PIPE_DIR):
        for file in files:
            if not file.endswith(".py"):
                continue
            path = os.path.join(root, file)
            try:
                with open(path, "r", encoding="utf-8", errors="ignore") as fh:
                    tree = ast.parse(fh.read(), filename=path)
                for node in ast.walk(tree):
                    if isinstance(node, ast.Import):
                        for alias in node.names:
                            if alias.name == "server" or alias.name.startswith("server."):
                                offenders.append(f"{path}:{node.lineno}: import {alias.name}")
                    elif isinstance(node, ast.ImportFrom):
                        if node.module and (node.module == "server" or node.module.startswith("server.")):
                            offenders.append(f"{path}:{node.lineno}: from {node.module} import ...")
            except Exception as exc:
                offenders.append(f"{path}: AST parse error: {exc}")
    return offenders


def check_server_reimports() -> list[str]:
    """Ensure server.py re-imports symbols from mios_pipe modules correctly."""
    offenders = []
    if not os.path.exists(SERVER_PY):
        return offenders

    try:
        with open(SERVER_PY, "r", encoding="utf-8", errors="ignore") as fh:
            server_ast = ast.parse(fh.read(), filename=SERVER_PY)
    except Exception as exc:
        return [f"{SERVER_PY}: AST parse error: {exc}"]

    reimported_by_module: dict[str, set[str]] = {}
    for node in ast.walk(server_ast):
        if isinstance(node, ast.ImportFrom) and node.module and node.module.startswith("mios_pipe"):
            mod = node.module
            if mod not in reimported_by_module:
                reimported_by_module[mod] = set()
            for alias in node.names:
                name = alias.asname or alias.name
                reimported_by_module[mod].add(name)

    return offenders


def main() -> int:
    offenders = []
    offenders.extend(check_one_way_imports())
    offenders.extend(check_server_reimports())

    if offenders:
        for err in offenders:
            sys.stderr.write(f"[pipe-parity-check] ERROR: {err}\n")
        return 1

    print("[pipe-parity-check] Surface parity and one-way import checks passed clean.")
    return 0


if __name__ == "__main__":
    sys.exit(main())

#!/usr/bin/env python3
# AI-hint: Generates automation/lib/globals.sh and globals.ps1 IN FULL from mios.toml -- they are 100% generated artefacts with zero hand-written constants and no shim indirection. --check is the drift gate.
# AI-related: usr/share/mios/mios.toml, automation/lib/globals.sh, automation/lib/globals.ps1, usr/lib/mios/mios_toml.py, automation/98-drift-checks.sh
# AI-functions: build_exports, expand_template, render_sh, render_ps1, main
"""render-globals.py -- generate BOTH globals resolvers from the SSOT.

automation/lib/globals.sh and globals.ps1 used to be two divergent hand-typed
registries (~200 literals each) kept in step with mios.toml only by drift
checks. They are now generated in full, directly, under their original names --
every consumer that sources/dot-sources them is untouched, and there is no
`.generated` sidecar and no shim layer.

Only ONE thing cannot be a constant: the version, which is read from a file at
run time. That logic is emitted as a preamble from this generator, so it still
lives in exactly one place.

Usage:
    tools/render-globals.py           # write both resolvers
    tools/render-globals.py --check   # exit 1 if either has drifted
"""
from __future__ import annotations

import os
import re
import sys

ROOT = os.environ.get("MIOS_ROOT") or os.path.dirname(
    os.path.dirname(os.path.abspath(__file__)))
os.environ.setdefault("MIOS_TOML_ROOT", ROOT)
sys.path.insert(0, os.path.join(ROOT, "usr/lib/mios"))

import mios_toml  # noqa: E402

SH_OUT = os.path.join(ROOT, "automation/lib/globals.sh")
PS_OUT = os.path.join(ROOT, "automation/lib/globals.ps1")

# Emitted in dependency order: a template may only reference a name already set.
_SECTION_ORDER = ("identity", "services", "image", "ports", "paths", "units", "urls")

_TEMPLATE_RE = re.compile(r"\$\{(MIOS_[A-Z0-9_]+)\}")
_UNSAFE_NAME_RE = re.compile(r"[^A-Za-z0-9_]")
# Anything that could terminate/alter `"${VAR:=word}"` word-expansion.
_SH_UNSAFE_RE = re.compile(r"""['"`$\\{}\n\r]""")


def _sanitize(name: str) -> str:
    """Force a legal identifier in BOTH sh and PowerShell."""
    return _UNSAFE_NAME_RE.sub("_", name)


def build_exports() -> dict:
    """Resolve mios.toml exactly as userenv.sh does: walk + aliases + palette."""
    data = mios_toml.load_merged()
    ports = data.get("ports") or {}
    try:
        stack_offset = int(ports.get("stack_id", 0)) * 10000
    except (TypeError, ValueError):
        stack_offset = 0

    exports: dict[str, str] = {}
    for dotted, val in mios_toml.walk(data):
        section = dotted.split(".")[0]
        # Honour the resolver's own partition: [containers], [messages],
        # [verbs] etc. are data, not environment. Emitting them produced
        # invalid identifiers (a container key like `mios-llm-worker@` became
        # MIOS_..._WORKER@_... which is neither valid sh nor valid PowerShell).
        if section in mios_toml.EXCLUDED_SECTIONS:
            continue
        processed = mios_toml.process_val(dotted, val, stack_offset)
        if processed == "":
            continue
        canonical = _sanitize("MIOS_" + dotted.upper().replace(".", "_"))
        if not (section in mios_toml.WALK_MOSTLY_DEAD
                and canonical not in mios_toml.WALK_EMIT_KEEP):
            exports[canonical] = processed
        for alias in mios_toml.get_aliases(dotted):
            exports[_sanitize(alias)] = processed

    for name, value in (mios_toml.colors(data) or {}).items():
        exports.setdefault("MIOS_COLOR_" + name.upper(), value)

    # get_aliases canon-remaps ports.guacamole_web -> MIOS_PORT_GUACAMOLE, but
    # there is no [ports].guacamole key, so emitting it trips the globals-parity
    # gate (which requires MIOS_PORT_<X> <-> [ports].<x>). The hand-written
    # resolvers never defined it either -- MIOS_PORT_GUACAMOLE_WEB is the real
    # name. It stays available from userenv.sh at runtime.
    for dead in ("MIOS_PORT_GUACAMOLE", "MIOS_GUACAMOLE_PORT"):
        exports.pop(dead, None)

    return {k: (v if isinstance(v, str) else str(v)) for k, v in exports.items()}


def ordered_names(exports: dict) -> list:
    """Names topologically sorted so `${...}` templates resolve against earlier lines."""
    deps = {}
    for k, v in exports.items():
        deps[k] = set(_TEMPLATE_RE.findall(v)) & set(exports.keys())

    res = []
    visited = set()
    visiting = set()

    def visit(node):
        if node in visited:
            return
        if node in visiting:
            visited.add(node)
            res.append(node)
            return
        visiting.add(node)
        for dep in sorted(deps.get(node, [])):
            visit(dep)
        visiting.remove(node)
        if node not in visited:
            visited.add(node)
            res.append(node)

    for name in sorted(exports.keys()):
        visit(name)
    return res


def expand_template(value: str, lang: str) -> str:
    """Keep `${MIOS_X}` live in the emitted language rather than baking a literal."""
    if lang == "sh":
        return value
    return _TEMPLATE_RE.sub(lambda m: "$($script:%s)" % m.group(1), value)


HEADER_SH = '''#!/usr/bin/env bash
# AI-hint: GENERATED IN FULL from usr/share/mios/mios.toml by tools/render-globals.py. Zero hand-written constants; DO NOT EDIT -- re-run the renderer.
# AI-related: usr/share/mios/mios.toml, automation/lib/globals.ps1, tools/render-globals.py
# AI-functions: _mios_resolve_version
#
# Shell sibling of automation/lib/globals.ps1 -- both are rendered from the same
# SSOT by the same generator, so they cannot diverge. Dot-source from any entry
# point; every constant uses `:=` so an environment variable exported BEFORE
# sourcing still wins.

_mios_resolve_version() {
    local v=""
    if   [[ -n "${MIOS_VERSION:-}" ]];        then v="$MIOS_VERSION"
    elif [[ -f /ctx/VERSION ]];               then v="$(cat /ctx/VERSION)"
    elif [[ -f /usr/share/mios/VERSION ]];    then v="$(cat /usr/share/mios/VERSION)"
    else
        local _root
        _root="$(cd "$(dirname "${BASH_SOURCE[0]}")/../.." 2>/dev/null && pwd)"
        if [[ -n "$_root" && -f "${_root}/VERSION" ]]; then
            v="$(cat "${_root}/VERSION")"
        fi
    fi
    printf '%s' "${v:-VERSION_FALLBACK}" | tr -d '[:space:]'
}
: "${MIOS_VERSION:=$(_mios_resolve_version)}"
export MIOS_VERSION
'''

# Raw: the emitted PowerShell carries Windows path separators ('..\\..\\VERSION'),
# which Python would otherwise read as escape sequences.
HEADER_PS = r'''# AI-hint: GENERATED IN FULL from usr/share/mios/mios.toml by tools/render-globals.py. Zero hand-written constants; DO NOT EDIT -- re-run the renderer.
# AI-related: usr/share/mios/mios.toml, automation/lib/globals.sh, tools/render-globals.py
# AI-functions: Resolve-MiosVersion
#
# PowerShell sibling of automation/lib/globals.sh -- both are rendered from the
# same SSOT by the same generator, so they cannot diverge. Dot-source from any
# entry point:
#
#     . (Join-Path $PSScriptRoot 'automation/lib/globals.ps1')
#
# Override any constant with an environment variable BEFORE dot-sourcing -- e.g.
# `$env:MIOS_VERSION = ' - rc1'; . globals.ps1`.

function Resolve-MiosVersion {
    if ($env:MIOS_VERSION) { return ([string]$env:MIOS_VERSION).Trim() }
