$script:MIOS_WSL_DISTRO = Resolve-MiosDistro
'''

# Windows-host paths resolve from the live environment, so they stay expressions.
# $defaultImageName is kept because check_globals_image_parity asserts on it.
PS_HOST_PATHS = '''
# ── IMAGE DEFAULT (asserted by the image-parity drift check) ─────────
$defaultImageName = 'IMAGE_NAME_LITERAL'
'''


PS_HOST_PATHS_TAIL = '''# ── WINDOWS HOST PATHS (resolved from the live environment) ──────────
$script:MIOS_WIN_APPDATA_DIR = if ($env:APPDATA)     { $env:APPDATA }     else { "$HOME/AppData/Roaming" }
$script:MIOS_WIN_DOCS_DIR    = if ($env:USERPROFILE) { "$env:USERPROFILE/Documents" } else { "$HOME/Documents" }
$script:MIOS_WIN_REPO_DIR    = if ($env:MIOS_WIN_REPO_DIR) { $env:MIOS_WIN_REPO_DIR } else { "$HOME/MiOS" }
'''


def _sh_squote(text: str) -> str:
    """POSIX single-quote: safe for EVERY byte, including } ( ) \\ and $."""
    return "'" + text.replace("'", "'\"'\"'") + "'"


def _sh_assign(name: str, value: str) -> str:
    """Assign-if-unset.

    Prefer the idiomatic `: "${VAR:=value}"` -- several drift checks parse that
    exact shape out of this file. It is unusable when the value contains `}`
    (message templates carry `{placeholder}`), which would close the expansion
    early and make the file a syntax error; those fall back to
    `[ -n "${VAR+x}" ] ||`, which has identical already-set-wins semantics.
    """
    parts = _TEMPLATE_RE.split(value)
    # The word in `"${VAR:=word}"` is still quote-processed, so a lone ' or "
    # inside it (e.g. "the operator's phone") starts an unterminated quote.
    # Only take the idiomatic form when the value is free of every metacharacter.
    if len(parts) == 1 and not _SH_UNSAFE_RE.search(value):
        return ': "${%s:=%s}"' % (name, value)
    if len(parts) == 1:
        rendered = _sh_squote(value)
    else:
        # odd indices are captured MIOS_* names -> keep them live as "$NAME"
        chunks = []
        for i, part in enumerate(parts):
            if i % 2:
                chunks.append('"${%s}"' % part)
            elif part:
                chunks.append(_sh_squote(part))
        rendered = "".join(chunks) or "''"
    return '[ -n "${%s+x}" ] || %s=%s' % (name, name, rendered)


def _ps_assign(name: str, value: str, exports: dict | None = None) -> str:
    parts = _TEMPLATE_RE.split(value)
    if len(parts) == 1 and re.fullmatch(r"\d+", value):
        # Bare integer, not a quoted string: ports really are numbers here, and
        # the globals-parity drift check parses `else { <digits> }`.
        rendered = value
    elif len(parts) == 1:
        rendered = "'%s'" % value.replace("'", "''")
    else:
        live_parts = [p for i, p in enumerate(parts) if i % 2 and (exports is not None and p in exports)]
        if not live_parts:
            rendered = "'%s'" % value.replace("'", "''")
        else:
            chunks = []
            for i, part in enumerate(parts):
                if i % 2:
                    if exports is None or part in exports:
                        chunks.append("$($script:%s)" % part)
                    else:
                        chunks.append("${%s}" % part)
                elif part:
                    # inside a PS double-quoted string, ` " $ are the metacharacters
                    chunks.append(part.replace("`", "``").replace('"', '`"')
                                  .replace("$", "`$"))
            rendered = '"%s"' % "".join(chunks)
    return "$script:%s = if ($env:%s) { $env:%s } else { %s }" % (
        name, name, name, rendered)


def render_sh(exports: dict, names: list, version_fallback: str) -> str:
    lines = [HEADER_SH.replace("VERSION_FALLBACK", version_fallback)]
    for name in names:
        if name == "MIOS_VERSION":
            continue
        lines.append(_sh_assign(name, exports[name]))
    lines.append("")
    return "\n".join(lines)


def render_ps1(exports: dict, names: list, version_fallback: str) -> str:
    lines = [HEADER_PS.replace("VERSION_FALLBACK", version_fallback)]
    for name in names:
        if name == "MIOS_VERSION":
            continue
        lines.append(_ps_assign(name, exports[name], exports))
    lines.append(PS_HOST_PATHS.replace(
        "IMAGE_NAME_LITERAL",
        exports.get("MIOS_IMAGE_NAME", "ghcr.io/mios-dev/mios").replace("'", "''")))
    lines.append(PS_HOST_PATHS_TAIL)
    return "\n".join(lines)


def main() -> int:
    check = "--check" in sys.argv
    exports = build_exports()
    version_fallback = exports.get("MIOS_META_VERSION") or exports.get("MIOS_VERSION") or "0.3.0"
    names = ordered_names(exports)

    outputs = {SH_OUT: render_sh(exports, names, version_fallback),
               PS_OUT: render_ps1(exports, names, version_fallback)}

    drifted = []
    for path, body in outputs.items():
        # .gitattributes pins `*.ps1 text eol=crlf` and `*.sh text eol=lf`, so
        # the CHECKED-OUT bytes differ per file type. Write the matching line
        # ending, and compare with newlines normalised so the gate can never
        # fail merely because a checkout honoured .gitattributes.
        eol = "\r\n" if path.endswith(".ps1") else "\n"
        existing = None
        if os.path.isfile(path):
            with open(path, encoding="utf-8-sig" if path.endswith(".ps1") else "utf-8") as fh:  # universal newlines
                existing = fh.read()
        if existing != body:
            drifted.append(path)
            if not check:
                enc = "utf-8-sig" if path.endswith(".ps1") else "utf-8"
                with open(path, "w", encoding=enc, newline=eol) as fh:
                    fh.write(body)

    if check:
        if drifted:
            sys.stderr.write("[render-globals] resolvers are stale vs SSOT:\n")
            for p in drifted:
                sys.stderr.write(f"    {os.path.relpath(p, ROOT)}\n")
            sys.stderr.write("    run: python3 tools/render-globals.py\n")
            return 1
        print(f"[render-globals] both resolvers match SSOT ({len(names)} constants)")
        return 0

    print(f"[render-globals] generated {len(names)} constants into "
          f"globals.sh + globals.ps1 (no hand-written literals remain)")
    return 0


if __name__ == "__main__":
    sys.exit(main())

#!/usr/bin/env python3
# AI-hint: Renders the flat [ports] projection from the [ports.categories] numbering SSOT -- every port is derived as base + index*stride, so an operator retargets a whole category by changing one base. --check is the drift gate.
# AI-related: usr/share/mios/mios.toml, automation/98-drift-checks.sh, usr/lib/mios/mios_toml.py, automation/lib/globals.generated.ps1
# AI-functions: derive_ports, category_band, find_violations, render_table, main
"""render-ports.py -- project [ports.categories] onto the flat [ports] table.

The categories table is the numbering SSOT: each category owns a `base`, a
`stride` and an ORDERED `members` list, and a member's port is

    base + index_in_members * stride

`pinned` entries (DNS/53) are protocol contracts and are emitted verbatim.

Usage:
    tools/render-ports.py            # rewrite the flat [ports] table in place
    tools/render-ports.py --check    # exit 1 if the flat table has drifted
    tools/render-ports.py --print    # print the derived name=port map
"""
from __future__ import annotations

import os
import re
import sys

try:
    import tomllib
except ModuleNotFoundError:  # py<3.11
    import tomli as tomllib  # type: ignore

ROOT = os.environ.get("MIOS_ROOT") or os.path.dirname(
    os.path.dirname(os.path.abspath(__file__)))
TOML = os.environ.get("MIOS_TOML") or os.path.join(ROOT, "usr/share/mios/mios.toml")


def _categories(data: dict) -> dict:
    return (data.get("ports") or {}).get("categories") or {}


def derive_ports(data: dict) -> dict:
    """Return {port_name: value} derived from [ports.categories].

    Pinned ports are emitted at their literal value; derived ports are
    base + index*stride. stack_id is applied later by the resolver's
    process_val(), not here, so this stays the pre-offset SSOT.
    """
    out: dict[str, int] = {}
    for cat, cfg in sorted(_categories(data).items()):
        if not isinstance(cfg, dict):
            continue
        base = int(cfg.get("base", 0))
        stride = int(cfg.get("stride", 1))
        for idx, member in enumerate(cfg.get("members") or []):
            out[member] = base + idx * stride
        for name, value in (cfg.get("pinned") or {}).items():
            out[name] = int(value)
    return out


def category_band(cfg: dict) -> tuple[int, int]:
    """Inclusive [lo, hi] the category's DERIVED members occupy."""
    base = int(cfg.get("base", 0))
    stride = int(cfg.get("stride", 1))
    n = len(cfg.get("members") or [])
    if n == 0:
        return (base, base)
    return (base, base + (n - 1) * stride)


def find_violations(data: dict) -> list[str]:
    """Schema integrity: single membership, no collisions, no band overlap,
    and flat-table agreement."""
    problems: list[str] = []
    cats = _categories(data)
    flat = {k: v for k, v in (data.get("ports") or {}).items()
            if isinstance(v, int) and k != "stack_id"}

    # 1. every port declared in exactly one category
    seen: dict[str, str] = {}
    for cat, cfg in sorted(cats.items()):
        if not isinstance(cfg, dict):
            continue
        names = list(cfg.get("members") or []) + list((cfg.get("pinned") or {}).keys())
        for name in names:
            if name in seen:
                problems.append(
                    f"port '{name}' is claimed by both [ports.categories.{seen[name]}] "
                    f"and [ports.categories.{cat}]")
            seen[name] = cat

    for name in sorted(flat):
        if name not in seen:
            problems.append(
                f"port '{name}' is in the flat [ports] table but belongs to no category")
    for name in sorted(seen):
        if name not in flat:
            problems.append(
                f"port '{name}' is declared in [ports.categories.{seen[name]}] "
                f"but missing from the flat [ports] table")

    # 2. no two ports share a value
    derived = derive_ports(data)
    by_value: dict[int, list[str]] = {}
    for name, value in sorted(derived.items()):
        by_value.setdefault(value, []).append(name)
    for value, names in sorted(by_value.items()):
        if len(names) > 1:
            problems.append(f"port collision at {value}: {', '.join(names)}")

    # 3. category bands must not overlap
    bands = []
    for cat, cfg in sorted(cats.items()):
        if isinstance(cfg, dict) and (cfg.get("members") or []):
            lo, hi = category_band(cfg)
            bands.append((lo, hi, cat))
    bands.sort()
    for (lo1, hi1, c1), (lo2, hi2, c2) in zip(bands, bands[1:]):
        if lo2 <= hi1:
            problems.append(
                f"category band overlap: {c1} [{lo1}-{hi1}] overlaps {c2} [{lo2}-{hi2}]")

    # 4. the rendered projection must equal the flat table
    for name in sorted(set(derived) & set(flat)):
        if derived[name] != flat[name]:
            problems.append(
                f"[ports].{name} = {flat[name]} but [ports.categories.{seen[name]}] "
                f"derives {derived[name]} -- run tools/render-ports.py")

    return problems


_PORT_LINE = re.compile(r"^(\s*)([a-z0-9_]+)(\s*)=(\s*)(\d+)(\s*)(#.*)?$")


def render_table(text: str, derived: dict) -> str:
    """Rewrite the scalar values inside the flat [ports] table, preserving
    key order, alignment and trailing comments."""
    lines = text.split("\n")
    start = None
    for i, line in enumerate(lines):
        if line.strip() == "[ports]":
            start = i
            break
    if start is None:
        raise SystemExit("render-ports: no [ports] table found")

    for i in range(start + 1, len(lines)):
        stripped = lines[i].strip()
        if stripped.startswith("["):
            break
        m = _PORT_LINE.match(lines[i].rstrip("\r"))
        if not m:
            continue
        indent, key, sp1, sp2, old, sp3, comment = m.groups()
        if key == "stack_id" or key not in derived:
            continue
        new = str(derived[key])
        # keep the '=' column stable: absorb the width delta into the gap
        pad = sp2 + " " * max(0, len(old) - len(new))
        if len(new) > len(old):
            pad = sp2[: max(1, len(sp2) - (len(new) - len(old)))]
        rebuilt = f"{indent}{key}{sp1}={pad}{new}"
        if comment:
            rebuilt += f"{sp3}{comment}"
        lines[i] = rebuilt + ("\r" if lines[i].endswith("\r") else "")
    return "\n".join(lines)


_FALLBACK_RE = re.compile(r"\$\{MIOS_PORT_([A-Z0-9_]+):-(\d+)\}")

# Consumers use the canonical alias remap for guacamole.
_ALIAS = {"GUACAMOLE": "GUACAMOLE_WEB"}

_SWEEP_PATHS = ("automation", "usr", "etc", "tools")
_SWEEP_SKIP = ("manifest.json", ".tsv", "/reference/", "/knowledge/",
               "/target/", "/.git/", "node_modules")


def _sweep_files(root: str):
    for top in _SWEEP_PATHS:
        for dirpath, dirnames, filenames in os.walk(os.path.join(root, top)):
            dirnames[:] = [d for d in dirnames
                           if d not in (".git", "target", "node_modules", "__pycache__")]
            for fn in filenames:
                path = os.path.join(dirpath, fn)
                rel = path.replace("\\", "/")
                if any(s in rel for s in _SWEEP_SKIP):
                    continue
                yield path


def sync_fallbacks(root: str, derived: dict, apply: bool) -> list:
    """`${MIOS_PORT_X:-1234}` literals are degrade-open defaults, but a
    hand-typed one silently goes stale the moment a category base moves. Treat
    them as GENERATED: rewrite every one to its SSOT value."""
    upper = {k.upper(): v for k, v in derived.items()}
    problems = []
    for path in _sweep_files(root):
        try:
            with open(path, "r", encoding="utf-8", newline="") as fh:
                text = fh.read()
        except (OSError, UnicodeDecodeError):
            continue
        if "MIOS_PORT_" not in text:
            continue

        changed = []

        def _repl(m):
            key, lit = m.group(1), m.group(2)
            name = _ALIAS.get(key, key)
            want = upper.get(name)
            if want is None or str(want) == lit:
                return m.group(0)
            changed.append((key, lit, want))
            return "${MIOS_PORT_%s:-%d}" % (key, want)

        new_text = _FALLBACK_RE.sub(_repl, text)
        if changed:
            rel = os.path.relpath(path, root).replace("\\", "/")
            for key, lit, want in changed:
                problems.append(f"{rel}: MIOS_PORT_{key} fallback :-{lit} != SSOT {want}")
            if apply:
                with open(path, "w", encoding="utf-8", newline="") as fh:
                    fh.write(new_text)
    return problems


def main() -> int:
    check = "--check" in sys.argv
    show = "--print" in sys.argv

    with open(TOML, "rb") as fh:
        data = tomllib.load(fh)

    derived = derive_ports(data)
    if show:
        for name, value in sorted(derived.items(), key=lambda kv: (kv[1], kv[0])):
            print(f"{value:>6}  {name}")
        return 0

    problems = find_violations(data)
    # In apply mode these are REPAIRED in place, so they are progress output,
    # not blockers -- only --check treats them as drift.
    fallback_problems = sync_fallbacks(ROOT, derived, apply=not check)
    if check:
        problems += fallback_problems
    elif fallback_problems:
        print(f"[render-ports] re-synced {len(fallback_problems)} stale "
              f"${{MIOS_PORT_*:-N}} fallback(s) from SSOT")

    if check:
        if problems:
            sys.stderr.write("[render-ports] port schema drift:\n")
            for p in problems:
                sys.stderr.write(f"    {p}\n")
            return 1
        print(f"[render-ports] {len(derived)} ports derive cleanly from "
              f"{len(_categories(data))} categories")
        return 0

    # membership/collision problems are NOT fixable by re-rendering
    fatal = [p for p in problems if "run tools/render-ports.py" not in p]
    if fatal:
        sys.stderr.write("[render-ports] cannot render, fix the schema first:\n")
        for p in fatal:
            sys.stderr.write(f"    {p}\n")
        return 1

    with open(TOML, "r", encoding="utf-8", newline="") as fh:
        text = fh.read()
    with open(TOML, "w", encoding="utf-8", newline="") as fh:
        fh.write(render_table(text, derived))
    print(f"[render-ports] rendered {len(derived)} ports into the flat [ports] table")
    return 0


if __name__ == "__main__":
    sys.exit(main())

#!/usr/bin/env python3
import os
import sys
import re
import glob

ROOT = os.environ.get("MIOS_ROOT") or os.path.dirname(
    os.path.dirname(os.path.abspath(__file__)))

try:
    import tomllib
except ModuleNotFoundError:  # py<3.11
    import tomli as tomllib  # type: ignore

def flatten_keys(d, prefix=""):
    keys = set()
    for k, v in d.items():
        full_key = f"{prefix}.{k}" if prefix else k
        keys.add(full_key)
        if isinstance(v, dict):
            keys.update(flatten_keys(v, full_key))
    return keys

def make_anchor(title):
    title = re.sub(r'\[([^\]]+)\]\([^)]+\)', r'\1', title)
    title = title.replace("`", "")
    out = []
    for char in title.lower():
        if char.isalnum() or char in (" ", "-", "_"):
            out.append(char)
    res = "".join(out).strip()
    res = re.sub(r'\s+', '-', res)
    res = re.sub(r'-+', '-', res)
    return res

def parse_simple_yaml(text):
    metadata = {}
    lines = text.strip().split("\n")
    in_multiline = None
    multiline_key = None
    multiline_val = []

    for line in lines:
        line = line.strip()
        if not line:
            continue
        if in_multiline:
            multiline_val.append(line)
            continue
        if ":" not in line:
            continue
        k, v = line.split(":", 1)
        k = k.strip()
        v = v.strip()
        if v == "|":
            in_multiline = True
            multiline_key = k
            multiline_val = []
            continue

        if v.startswith("[") and v.endswith("]"):
            items = [x.strip().strip('"').strip("'") for x in v[1:-1].split(",") if x.strip()]
            coerced = []
            for x in items:
                try:
                    coerced.append(int(x))
                except ValueError:
                    coerced.append(x)
            v = coerced
        metadata[k] = v

    if in_multiline and multiline_key:
        metadata[multiline_key] = "\n".join(multiline_val)
    return metadata

def main(argv):
    check = "--check" in argv
    roadmap_path = os.path.join(ROOT, "ROADMAP.md")

    if not os.path.exists(roadmap_path):
        print(f"ERROR: ROADMAP.md not found at {roadmap_path}", file=sys.stderr)
        return 1

    valid_ssot_keys = set()
    userenv_path = os.path.join(ROOT, "tools/lib/userenv.sh")
    if os.path.exists(userenv_path):
        with open(userenv_path, "r", encoding="utf-8") as f:
            userenv_content = f.read()
        for m in re.finditer(r'\("([a-zA-Z0-9_.-]+)"\s*,\s*"[A-Z0-9_]+"\)', userenv_content):
            valid_ssot_keys.add(m.group(1))

    toml_path = os.path.join(ROOT, "usr/share/mios/mios.toml")
    if os.path.exists(toml_path):
        with open(toml_path, "rb") as f:
            toml_data = tomllib.load(f)
        valid_ssot_keys.update(flatten_keys(toml_data))

    def check_adr_exists(adr_num):
        prefix = f"{adr_num:04d}"
        search_path = os.path.join(ROOT, "usr/share/doc/mios/adr", f"{prefix}-*.md")
        files = glob.glob(search_path)
        return len(files) > 0

    with open(roadmap_path, "r", encoding="utf-8") as f:
        lines = f.readlines()

    current_part = None
    workstreams = []
    parts_order = []
    part_workstreams = {}

    idx = 0
    while idx < len(lines):
        line = lines[idx]
        if line.startswith("# ") and not line.startswith("## "):
            header_name = line[2:].strip()
            if not any(header_name.lower().startswith(x) for x in ["mios -- master roadmap", "mios roadmap", "archived mios roadmap", "appendix"]):
                current_part = header_name
                if current_part not in parts_order:
                    parts_order.append(current_part)
                    part_workstreams[current_part] = []
                idx += 1
                continue


        if line.startswith("## WS-"):
            header_text = line[2:].strip()
            parts = re.split(r'\s+[-—–]+\s+', header_text, maxsplit=1)
            ws_id = parts[0].strip()
            ws_title = parts[1].strip() if len(parts) > 1 else header_text

            frontmatter_text = ""
            fm_idx = idx + 1
            while fm_idx < len(lines) and not lines[fm_idx].strip():
                fm_idx += 1

            if fm_idx < len(lines) and lines[fm_idx].strip().startswith("<!--"):
                block_lines = []
                first_line = lines[fm_idx].strip()
                if first_line.endswith("-->"):
                    block_lines.append(first_line[4:-3])
                    fm_idx += 1
                else:
                    block_lines.append(first_line[4:])
                    fm_idx += 1
                    while fm_idx < len(lines):
                        cur_line = lines[fm_idx]
                        if "-->" in cur_line:
                            block_lines.append(cur_line.split("-->", 1)[0])
                            fm_idx += 1
                            break
                        else:
                            block_lines.append(cur_line)
                            fm_idx += 1
                block_text = "\n".join(block_lines)
                if "id:" in block_text or "status:" in block_text:
                    frontmatter_text = block_text

            meta = {}
            if frontmatter_text:
                meta = parse_simple_yaml(frontmatter_text)

            meta["id"] = meta.get("id") or ws_id
            meta["title"] = meta.get("title") or ws_title

            if "status" not in meta:
                rest_of_text = ""
                for j in range(idx, min(idx + 15, len(lines))):
                    rest_of_text += lines[j]
                if "✅" in rest_of_text or "DONE" in rest_of_text:
                    meta["status"] = "done"
                elif "active" in rest_of_text.lower():
                    meta["status"] = "active"
                else:
                    meta["status"] = "proposed"

            meta["priority"] = meta.get("priority") or "P2"
            meta["laws"] = meta.get("laws") or []
            meta["ssot_keys"] = meta.get("ssot_keys") or []
            meta["adr"] = meta.get("adr") or []
            meta["deps"] = meta.get("deps") or []
            meta["acceptance"] = meta.get("acceptance") or ""
            meta["theme"] = meta.get("theme") or "General"
            meta["part"] = current_part

            workstreams.append(meta)
            if current_part:
                part_workstreams[current_part].append(meta)

        idx += 1

    # The law set is the SSOT's, not a literal: this was pinned at 13 and went
    # stale when the registry grew, so no workstream could cite Laws 14-16.
    valid_law_ids = set()
    try:
        with open(os.path.join(ROOT, "usr/share/mios/mios.toml"), "rb") as fh:
            for law in (tomllib.load(fh).get("laws", {}) or {}).get("laws", []) or []:
                if isinstance(law.get("id"), int):
                    valid_law_ids.add(law["id"])
    except (OSError, tomllib.TOMLDecodeError):
        valid_law_ids = set()

    validation_errors = []
    for ws in workstreams:
        for law in ws["laws"]:
            if not isinstance(law, int) or (valid_law_ids and law not in valid_law_ids):
                validation_errors.append(f"Workstream {ws['id']} cites invalid Law: {law}")

        for adr in ws["adr"]:
            if not isinstance(adr, int) or not check_adr_exists(adr):
                validation_errors.append(f"Workstream {ws['id']} cites non-existent ADR: {adr}")

        for key in ws["ssot_keys"]:
            if key not in valid_ssot_keys:
                validation_errors.append(f"Workstream {ws['id']} cites non-existent SSOT key: {key}")

    if validation_errors:
        print("[roadmap-index] Validation failed:", file=sys.stderr)
        for err in validation_errors:
            print(f"  - {err}", file=sys.stderr)
        return 2

    toc_lines = ["## Table of Contents"]
    for part in parts_order:
        anchor = make_anchor(part)
        toc_lines.append(f"- [{part}](#{anchor})")
    toc_content = "\n".join(toc_lines) + "\n"

    rollup_counts = {"done": 0, "active": 0, "proposed": 0, "blocked": 0}
    for ws in workstreams:
        status = ws["status"].lower()
        if status in rollup_counts:
            rollup_counts[status] += 1
        else:
            rollup_counts["proposed"] += 1

    rollup_lines = [
        "### Workstream Status Rollup",
        f"- **Done**: {rollup_counts['done']}",
        f"- **Active**: {rollup_counts['active']}",
        f"- **Proposed**: {rollup_counts['proposed']}",
        f"- **Blocked**: {rollup_counts['blocked']}"
    ]
    rollup_content = "\n".join(rollup_lines) + "\n"

    index_lines = ["### Workstream Index\n"]
    for part in parts_order:
        index_lines.append(f"**{part}**")
        ws_list = part_workstreams[part]
        if not ws_list:
            index_lines.append("(no workstreams)\n")
        else:
            for ws in ws_list:
                status_suffix = " ✅" if ws["status"].lower() == "done" else f" ({ws['status'].lower()})"
                index_lines.append(f"- `{ws['id']}` — {ws['title']}{status_suffix}")
            index_lines.append("")
    index_content = "\n".join(index_lines)

    with open(roadmap_path, "r", encoding="utf-8") as f:
        file_text = f.read()

    def replace_section(text, start_marker, end_marker, replacement):
        pattern = re.compile(
            re.escape(start_marker) + r".*?" + re.escape(end_marker),
            re.DOTALL
        )
        if not pattern.search(text):
            raise ValueError(f"Markers {start_marker} and {end_marker} not found")
        return pattern.sub(start_marker + "\n" + replacement + end_marker, text)

    try:
        new_text = file_text
        new_text = replace_section(new_text, "<!-- ROADMAP_ROLLUP_START -->", "<!-- ROADMAP_ROLLUP_END -->", rollup_content)
        new_text = replace_section(new_text, "<!-- ROADMAP_INDEX_START -->", "<!-- ROADMAP_INDEX_END -->", index_content)
        new_text = replace_section(new_text, "<!-- ROADMAP_TOC_START -->", "<!-- ROADMAP_TOC_END -->", toc_content)
    except ValueError as e:
        print(f"ERROR: {e}", file=sys.stderr)
        return 1

    if check:
        if file_text != new_text:
            print("[roadmap-index] DRIFT detected: ROADMAP.md index is stale", file=sys.stderr)
            return 1
        print("[roadmap-index] ROADMAP.md index is in sync")
        return 0

    with open(roadmap_path, "w", encoding="utf-8", newline="\n") as f:
        f.write(new_text)
    print("[roadmap-index] Successfully regenerated Table of Contents, Index, and Rollup in ROADMAP.md")
    return 0

if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))

# AI-hint: Opt-in Authenticode signing script for shipped Windows PowerShell scripts.
[CmdletBinding()]
param(
    [string]$CertPath = "",
    # SecureString, never [string]. A plaintext password parameter forces
    # ConvertTo-SecureString -AsPlainText, which PSScriptAnalyzer rejects
    # (PSAvoidUsingConvertToSecureStringWithPlainText) because it puts the
    # secret in process memory and command history in the clear.
    [System.Security.SecureString]$CertPassword,
    [string[]]$ScriptPaths = @()
)

$ErrorActionPreference = 'Stop'
$rootDir = $PSScriptRoot
if (-not $rootDir) { $rootDir = (Get-Location).Path }
$repoRoot = (Get-Item $rootDir).Parent.FullName

# Resolve cert from parameters, env vars, or mios.toml
if (-not $CertPath) {
    $CertPath = $env:MIOS_SECURITY_POWERSHELL_SIGNING_SIGNING_CERT
    if (-not $CertPath) { $CertPath = $env:MIOS_SIGNING_CERT }
}

if (-not $CertPath) {
    $tomlPath = Join-Path $repoRoot "usr\share\mios\mios.toml"
    if (Test-Path $tomlPath) {
        $lines = Get-Content $tomlPath
        $inSec = $false
        foreach ($line in $lines) {
            if ($line -match '^\s*\[security\.powershell_signing\]') { $inSec = $true; continue }
            if ($inSec -and $line -match '^\s*\[') { break }
            if ($inSec -and $line -match '^\s*signing_cert\s*=\s*"(.*)"') {
                $CertPath = $matches[1]
            }
            # NOTE: the signing password is deliberately NOT read from
            # mios.toml. SSOT is committed to git; a signing secret there is
            # a leaked secret. Supply it as a SecureString parameter, or let
            # the prompt below collect it.
        }
    }
}

if (-not $CertPath) {
    Write-Host "[sign-powershell] INFO: No signing cert configured in mios.toml [security.powershell_signing]. Skipping signing (opt-in / degrade open)." -ForegroundColor Yellow
    exit 0
}

if (-not (Test-Path $CertPath)) {
    Write-Host "[sign-powershell] WARNING: Signing cert path '$CertPath' does not exist. Skipping signing." -ForegroundColor Yellow
    exit 0
}

# Resolve default script targets if none provided
if ($ScriptPaths.Count -eq 0) {
    $targets = @("Get-MiOS.ps1", "build-mios.ps1", "bootstrap.ps1")
    foreach ($t in $targets) {
        $p = Join-Path $repoRoot $t
        if (Test-Path $p) { $ScriptPaths += $p }
    }
    $winDir = Join-Path $repoRoot "usr\share\mios\windows"
    if (Test-Path $winDir) {
        Get-ChildItem -Path $winDir -Filter "*.ps1" | ForEach-Object { $ScriptPaths += $_.FullName }
    }
}

Write-Host "[sign-powershell] Signing $($ScriptPaths.Count) script(s) with $CertPath..." -ForegroundColor Cyan

$securePass = $CertPassword
if ($CertPath -match '\.pfx$|\.p12$' -and -not $securePass) {
    # Collect interactively rather than accepting plaintext from anywhere.
    $securePass = Read-Host -Prompt "Password for $CertPath" -AsSecureString
}

$cert = $null
if ($CertPath -match '\.pfx$|\.p12$') {
    $cert = New-Object System.Security.Cryptography.X509Certificates.X509Certificate2($CertPath, $securePass)
} else {
    $cert = Get-Item "Cert:\LocalMachine\My\$CertPath" -ErrorAction SilentlyContinue
    if (-not $cert) {
        $cert = Get-Item "Cert:\CurrentUser\My\$CertPath" -ErrorAction SilentlyContinue
    }
}

if (-not $cert) {
    Write-Host "[sign-powershell] ERROR: Failed to load certificate from '$CertPath'." -ForegroundColor Red
    exit 1
}

$signedCount = 0
foreach ($scriptFile in $ScriptPaths) {
    $sig = Set-AuthenticodeSignature -FilePath $scriptFile -Certificate $cert -ErrorAction SilentlyContinue
    if ($sig.Status -eq 'Valid') {
        Write-Host "  [SIGNED] $scriptFile" -ForegroundColor Green
        $signedCount++
    } else {
        Write-Host "  [WARN] Failed to sign $scriptFile status=$($sig.Status)" -ForegroundColor Yellow
    }
}

Write-Host "[sign-powershell] Successfully signed $signedCount / $($ScriptPaths.Count) scripts." -ForegroundColor Cyan
exit 0

# AI-hint: Updates metadata in wiki markdown files by injecting current version and RAG sync timestamps into JSON blocks to ensure documentation reflects the latest system state and artifact availability.
# AI-functions: get_last_rag_sync, get_version, sync_json_embeds, update_knowledge, update_status, sync_wiki
import os
import re
import json
from datetime import datetime

def get_last_rag_sync():
    rag_file = "artifacts/repo-rag-snapshot.json.gz"
    if os.path.exists(rag_file):
        mtime = os.path.getmtime(rag_file)
        return datetime.fromtimestamp(mtime).isoformat()
    return datetime.now().isoformat()

def get_version():
    if os.path.exists("VERSION"):
        with open("VERSION", "r") as f:
            return f.read().strip()
    return "0.3.0"

def sync_json_embeds(file_path):
    if not os.path.exists(file_path):
        return

    with open(file_path, 'r') as f:
        content = f.read()

    version = get_version()
    rag_sync = get_last_rag_sync()

    def update_knowledge(match):
        try:
            data = json.loads(match.group(1))
            data["last_rag_sync"] = rag_sync
            data["version"] = version
            return f"```json:knowledge\n{json.dumps(data, indent=2)}\n```"
        except:
            return match.group(0)

    content = re.sub(r"```json:knowledge\n(.*?)\n```", update_knowledge, content, flags=re.DOTALL)

    def update_status(match):
        try:
            data = json.loads(match.group(1))
            if "baseline" in data:
                data["baseline"] = f"v{version}"
            if "last_build" in data or True: # Force add if not present for tracking
                 data["last_sync"] = rag_sync
            return f"```json\n{json.dumps(data, indent=2)}\n```"
        except:
            return match.group(0)

    content = re.sub(r"#  'MiOS': Immutable Cloud-Native Workstation\n\n```json\n(.*?)\n```", 
                     r"#  'MiOS': Immutable Cloud-Native Workstation\n\n```json\n\1\n```", content, flags=re.DOTALL)
    content = re.sub(r"```json\n(\{.*?\})\n```", update_status, content, flags=re.DOTALL)

    with open(file_path, 'w') as f:
        f.write(content)
    print(f"[ok] Propagated sync values to {file_path}")

def sync_wiki():
    print(" Syncing Wiki Documentation...")

    automation_dir = "automation"
    automation_doc = "specs/engineering/2026-04-26-Artifact-ENG-002-Scripts-Index.md"

    knowledge_meta = {
        "summary": "Automated index of all 'MiOS' automation automation.",
        "logic_type": "automation",
        "tags": ["automation", "automation", "index"],
        "version": get_version(),
        "last_rag_sync": get_last_rag_sync()
    }

    content = f"""<!--  'MiOS' Artifact | Proprietor: 'MiOS' Project | https://github.com/MiOS-DEV/mios -->
> **Generated:** {datetime.now().isoformat()}
> **Status:** Automated Sync

```json:knowledge
{json.dumps(knowledge_meta, indent=2)}
```

This file provides a machine-readable and human-readable index of all automation automation in the `automation/` directory.

"""
    for script in sorted(os.listdir(automation_dir)):
        if script.endswith(".sh"):
            path = os.path.join(automation_dir, script)
            description = "No description available."
            try:
                with open(path, 'r') as f:
                    lines = f.readlines()
                    for line in lines:
                        clean_line = line.strip()
                        if clean_line.startswith("# ") and not clean_line.startswith("#!") and "===" not in clean_line:
                            description = clean_line[2:].strip()
                            if description:
                                break
            except:
                pass
            content += f"## `{script}`\n- **Path:** `{path}`\n- **Description:** {description}\n\n"

    content += "<!--  'MiOS' Proprietary Artifact | Copyright (c) 2026 'MiOS' Project -->"

    os.makedirs(os.path.dirname(automation_doc), exist_ok=True)
    with open(automation_doc, 'w') as f:
        f.write(content)
    print(f"[ok] Updated {automation_doc}")

    target_files = ["README.md", "usr/share/mios/ai/INDEX.md", "usr/share/mios/ai/INDEX.md", "usr/share/mios/ai/INDEX.md", "usr/share/mios/ai/INDEX.md", "specs/Home.md"]
    for f in target_files:
        sync_json_embeds(f)

if __name__ == "__main__":
    sync_wiki()

#!/usr/bin/env python3
# AI-hint: Unit tests for render-globals.py -- proves shell and PowerShell constants are escaped so the generated resolvers always parse, that ${MIOS_X} templates stay live in both languages, and that dependency ordering puts a template after the name it references.
# AI-related: tools/render-globals.py, automation/lib/globals.sh, automation/lib/globals.ps1
# AI-functions: load_module, TestShAssign, TestPsAssign, TestOrdering, TestSanitize

import importlib.util
import os
import re
import unittest

_HERE = os.path.dirname(os.path.abspath(__file__))


def load_module():
    spec = importlib.util.spec_from_file_location(
        "render_globals", os.path.join(_HERE, "render-globals.py"))
    mod = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(mod)
    return mod


rg = load_module()


class TestShAssign(unittest.TestCase):
    def test_simple_value_uses_the_idiomatic_form(self):
        # several drift checks parse this exact shape out of globals.sh
        self.assertEqual(rg._sh_assign("MIOS_PORT_SSH", "8100"),
                         ': "${MIOS_PORT_SSH:=8100}"')

    def test_value_with_a_brace_avoids_the_expansion_form(self):
        # a `}` would close ${VAR:= early and break the whole file
        out = rg._sh_assign("MIOS_MSG", "hello {name}")
        self.assertNotIn(":=", out)
        self.assertIn("MIOS_MSG+x", out)

    def test_value_with_an_apostrophe_is_quoted_safely(self):
        # "the operator's phone" previously produced an unterminated quote
        out = rg._sh_assign("MIOS_JOB", "the operator's phone")
        self.assertNotIn(":=", out)
        self.assertIn("""'"'"'""", out)

    def test_template_stays_live(self):
        out = rg._sh_assign("MIOS_FORGE_URL",
                            "http://localhost:${MIOS_PORT_FORGE_HTTP}")
        self.assertIn('"${MIOS_PORT_FORGE_HTTP}"', out)

    def test_assignment_is_conditional_so_env_wins(self):
        for value in ("8100", "has }brace", "has 'quote"):
            out = rg._sh_assign("MIOS_X", value)
            self.assertTrue(":=" in out or "+x" in out, out)


class TestPsAssign(unittest.TestCase):
    def test_numeric_is_emitted_bare(self):
        # check 28 parses `else { <digits> }`
        out = rg._ps_assign("MIOS_PORT_SSH", "8100")
        self.assertIn("else { 8100 }", out)

    def test_string_is_single_quoted(self):
        out = rg._ps_assign("MIOS_USER", "mios")
        self.assertIn("else { 'mios' }", out)

    def test_embedded_quote_is_doubled(self):
        out = rg._ps_assign("MIOS_JOB", "operator's phone")
        self.assertIn("''", out)

    def test_template_becomes_a_subexpression(self):
        out = rg._ps_assign("MIOS_FORGE_URL",
                            "http://localhost:${MIOS_PORT_FORGE_HTTP}")
        self.assertIn("$($script:MIOS_PORT_FORGE_HTTP)", out)

    def test_dollar_in_a_template_value_is_escaped(self):
        out = rg._ps_assign("MIOS_X", "a $literal and ${MIOS_PORT_SSH}")
        self.assertIn("`$literal", out)

    def test_env_override_still_wins(self):
        out = rg._ps_assign("MIOS_PORT_SSH", "8100")
        self.assertIn("if ($env:MIOS_PORT_SSH)", out)


class TestSanitize(unittest.TestCase):
    def test_illegal_identifier_characters_are_replaced(self):
        # a container key like mios-llm-worker@ produced MIOS_..._WORKER@_...
        # which is neither valid sh nor valid PowerShell
        self.assertEqual(rg._sanitize("MIOS_A@B-C.D"), "MIOS_A_B_C_D")

    def test_legal_name_is_untouched(self):
        self.assertEqual(rg._sanitize("MIOS_PORT_SSH"), "MIOS_PORT_SSH")


class TestOrdering(unittest.TestCase):
    def test_template_is_emitted_after_the_name_it_references(self):
        exports = {
            "MIOS_URLS_FORGE": "http://localhost:${MIOS_PORT_FORGE_HTTP}",
            "MIOS_PORT_FORGE_HTTP": "8400",
        }
        names = rg.ordered_names(exports)
        self.assertLess(names.index("MIOS_PORT_FORGE_HTTP"),
                        names.index("MIOS_URLS_FORGE"))


class TestExpandTemplate(unittest.TestCase):
    def test_shell_keeps_the_brace_form(self):
        self.assertEqual(rg.expand_template("a${MIOS_X}b", "sh"), "a${MIOS_X}b")

    def test_powershell_uses_script_scope(self):
        self.assertEqual(rg.expand_template("a${MIOS_X}b", "ps"),
                         "a$($script:MIOS_X)b")


class TestGeneratedFilesAreParseable(unittest.TestCase):
    def test_generated_sh_has_balanced_quoting(self):
        """Whole-file, not per-line: a value may legitimately be multi-line
        (e.g. MIOS_OWUI_SYSTEM_PROMPT_TEMPLATE), and single quotes span
        newlines in shell, so a per-line balance check false-alarms."""
        path = os.path.join(os.path.dirname(_HERE), "automation/lib/globals.sh")
        if not os.path.isfile(path):
            self.skipTest("globals.sh not generated in this tree")
        with open(path, encoding="utf-8") as fh:
            body = fh.read()
        stripped = body.replace("""'"'"'""", "")
        self.assertEqual(stripped.count("'") % 2, 0,
                         "globals.sh has an unbalanced single quote")

    def test_generated_ps1_uses_legal_identifiers(self):
        path = os.path.join(os.path.dirname(_HERE), "automation/lib/globals.ps1")
        if not os.path.isfile(path):
            self.skipTest("globals.ps1 not generated in this tree")
        with open(path, encoding="utf-8") as fh:
            names = re.findall(r"^\$script:([^\s=]+)\s*=", fh.read(), re.M)
        self.assertTrue(names, "no constants found in globals.ps1")
        for name in names:
            self.assertRegex(name, r"^[A-Za-z0-9_]+$",
                             f"illegal PowerShell identifier: {name}")


if __name__ == "__main__":
    unittest.main()

#!/usr/bin/env python3
# AI-hint: Validates verb command templates against declared verb arguments and synonyms at build time.
import os
import sys

sys.path.insert(0, os.path.join(os.path.dirname(__file__), "..", "usr", "lib", "mios", "agent-pipe"))

try:
    import tomllib
except ImportError:
    import tomli as tomllib

from mios_template import compile_template, _TEMPLATE_PH_RE

def main():
    root = os.path.abspath(os.path.join(os.path.dirname(__file__), ".."))
    toml_path = os.path.join(root, "usr", "share", "mios", "mios.toml")
    if not os.path.isfile(toml_path):
        print(f"ERROR: SSOT toml file not found at {toml_path}", file=sys.stderr)
        sys.exit(1)

    try:
        with open(toml_path, "rb") as f:
            data = tomllib.load(f)
    except Exception as e:
        print(f"ERROR: Failed to parse {toml_path}: {e}", file=sys.stderr)
        sys.exit(1)

    verbs = data.get("verbs", {})
    if not verbs:
        print("ERROR: No [verbs] section in mios.toml", file=sys.stderr)
        sys.exit(1)

    errors = []

    for vname, vspec in verbs.items():
        if not isinstance(vspec, dict):
            continue

        cmd_keys = [k for k in ("cmd", "cmd_args", "cmd_positioned", "cmd_pixel", "cmd_resize") if k in vspec]
        for k in cmd_keys:
            tmpl_str = vspec[k]
            if not isinstance(tmpl_str, str):
                continue

            if tmpl_str.count("{") != tmpl_str.count("}"):
                errors.append(f"Verb '{vname}' field '{k}' template has unclosed or mismatched braces: '{tmpl_str}'")
                continue

            try:
                ct = compile_template(tmpl_str)
            except Exception as e:
                errors.append(f"Verb '{vname}' field '{k}' template unparseable: {e}")
                continue

    if errors:
        for err in errors:
            print(f"::error::{err}", file=sys.stderr)
        sys.exit(1)

    print("[verb-template-check] PASS: All verb templates compiled and validated clean.")
    sys.exit(0)

if __name__ == "__main__":
    main()

#!/usr/bin/env python3
# AI-hint: A utility script that uses regex to wrap the "MiOS" proper noun in single quotes in documentation and config files to ensure legal-attribution compliance while ignoring internal identifiers and paths.
# AI-functions: is_allowed, process

import re, sys
from pathlib import Path

_LIT = "M" + "iOS"
PATTERN = re.compile(rf"(?<!['\w\"/\\]){_LIT}(?![-./\\\w'\"])")
REPLACE = f"'{_LIT}'"

ALLOW_EXT = {
    ".md", ".sh", ".ps1", ".py", ".toml", ".conf", ".service",
    ".target", ".container", ".preset", ".txt", ".rules", ".cfg",
}
ALLOW_NAMES = {"Containerfile", "Justfile"}

def is_allowed(path: Path) -> bool:
    if path.name in ALLOW_NAMES:
        return True
    if path.suffix in ALLOW_EXT:
        return True
    return False

def process(path: Path) -> int:
    """Return number of replacements made."""
    try:
        text = path.read_text(encoding="utf-8")
    except (UnicodeDecodeError, IsADirectoryError, PermissionError):
        return 0
    new, n = PATTERN.subn(REPLACE, text)
    if n:
        path.write_text(new, encoding="utf-8")
    return n

if __name__ == "__main__":
    total_files = 0
    total_subs = 0
    for arg in sys.argv[1:]:
        p = Path(arg)
        if not p.is_file():
            continue
        if not is_allowed(p):
            continue
        n = process(p)
        if n:
            print(f"{n:4d}  {arg}")
            total_files += 1
            total_subs += n
    print(f"\n{total_subs} replacements across {total_files} files", file=sys.stderr)

﻿# AI-hint: PowerShell entry point for Windows environments to build the MiOS OCI image via Docker and convert it into a bootable VHDX, raw, or qcow2 disk image using bootc-image-builder.
# AI-related: mios-bib
# AI-functions: Write-Step, Write-Ok, Write-Warn, Write-Fail
#Requires -Version 5.1
<#
.SYNOPSIS
    'MiOS' local build entry point for Windows (Docker Desktop + WSL2).

.DESCRIPTION
    Builds the 'MiOS' OCI image locally using Docker Desktop (WSL2 backend),
    then uses bootc-image-builder to produce a VHDX for Hyper-V import.

.PARAMETER OutputFormat
    Disk image format to produce: vhdx (default), raw, qcow2, wsl2

.PARAMETER Tag
    Local image tag (default: mios:local)

.PARAMETER SkipBib
    Build the container image only; skip bootc-image-builder disk conversion.

.EXAMPLE
    .\Build-MiOS.ps1
    .\Build-MiOS.ps1 -OutputFormat wsl2
    .\Build-MiOS.ps1 -SkipBib
#>
param(
    [ValidateSet('vhdx','raw','qcow2','wsl2')]
    [string]$OutputFormat = 'vhdx',
    [string]$Tag = 'mios:local',
    [switch]$SkipBib
)

Set-StrictMode -Version Latest
$ErrorActionPreference = 'Stop'

$exportModule = Join-Path $PSScriptRoot '..\..\usr\libexec\mios\MiOS.Export.psm1'
if (Test-Path $exportModule) { Import-Module $exportModule -ErrorAction SilentlyContinue }
if (-not (Get-Command Write-Step -ErrorAction SilentlyContinue)) {
    function Write-Step { param([string]$Msg) Write-Host "==> $Msg" -ForegroundColor Cyan }
    function Write-Ok   { param([string]$Msg) Write-Host " ok $Msg" -ForegroundColor Green }
    function Write-Warn { param([string]$Msg) Write-Host "WARN $Msg" -ForegroundColor Yellow }
    function Write-Fail { param([string]$Msg) Write-Host "FAIL $Msg" -ForegroundColor Red; exit 1 }
}

# ── Preflight ──────────────────────────────────────────────────────────────
Write-Step "Preflight checks"

if (-not (Get-Command docker -ErrorAction SilentlyContinue)) {
    Write-Fail "docker not found. Install Docker Desktop: https://www.docker.com/products/docker-desktop/"
}
$dockerInfo = docker info 2>&1
if ($LASTEXITCODE -ne 0) {
    Write-Fail "Docker daemon not running. Start Docker Desktop and try again."
}
if ($dockerInfo -notmatch 'WSL') {
    Write-Warn "Docker Desktop does not appear to be using the WSL2 backend. Build may be slower."
}

if (-not (Test-Path 'Containerfile')) {
    Write-Fail "Containerfile not found. Run this script from the 'MiOS' repo root."
}
Write-Ok "Docker Desktop + Containerfile found"

# ── Environment variables ──────────────────────────────────────────────────
Write-Step "Loading build environment"

# Load from the unified ~/.config/mios/mios.toml (or legacy env.toml fallback).
$UnifiedToml = "$HOME\.config\mios\mios.toml"
$LegacyEnv   = "$HOME\.config\mios\env.toml"
$ConfigToml  = if (Test-Path $UnifiedToml) { $UnifiedToml }
               elseif (Test-Path $LegacyEnv) { $LegacyEnv }
               else { $null }
if ($ConfigToml) {
    Write-Ok "Reading $ConfigToml"
    # Flat KEY = "value" lines. Sectioned subkeys (user.name, image.base, ...)
    # not parsed here -- the canonical reader is tools/lib/userenv.sh on the
    # Linux side. This Windows-side loader only needs MIOS_USER_PASSWORD_HASH
    # and MIOS_SSH_PUBKEY which are flat KEY=VALUE in either file.
    Get-Content $ConfigToml | ForEach-Object {
        if ($_ -match '^\s*(MIOS_\w+)\s*=\s*"?([^"#]+)"?') {
            $k = $Matches[1]; $v = $Matches[2].Trim()
            if (-not [System.Environment]::GetEnvironmentVariable($k)) {
                [System.Environment]::SetEnvironmentVariable($k, $v)
                Write-Host "  $k = $v"
            }
        }
    }
}

# Mandatory secrets -- prompt if not set
if (-not $env:MIOS_USER_PASSWORD_HASH) {
    $pw = Read-Host -Prompt "MIOS_USER_PASSWORD_HASH (openssl passwd -6 <password>)"
    $env:MIOS_USER_PASSWORD_HASH = $pw
}
if (-not $env:MIOS_SSH_PUBKEY) {
    $key = Read-Host -Prompt "MIOS_SSH_PUBKEY (your SSH public key, or Enter to skip)"
    if ($key) { $env:MIOS_SSH_PUBKEY = $key }
}

# ── Build OCI image ────────────────────────────────────────────────────────
Write-Step "Building 'MiOS' OCI image ($Tag)"

$BuildArgs = @(
    'build',
    '--tag', $Tag,
    '--file', 'Containerfile',
    '--build-arg', "MIOS_USER_PASSWORD_HASH=$env:MIOS_USER_PASSWORD_HASH"
)
if ($env:MIOS_SSH_PUBKEY) {
    $BuildArgs += '--build-arg', "MIOS_SSH_PUBKEY=$env:MIOS_SSH_PUBKEY"
}
$BuildArgs += '.'

docker @BuildArgs
if ($LASTEXITCODE -ne 0) { Write-Fail "docker build failed (exit $LASTEXITCODE)" }
Write-Ok "OCI image built: $Tag"

if ($SkipBib) {
    Write-Ok "Done (SkipBib set -- skipping disk image conversion)"
    exit 0
}

# ── bootc-image-builder ────────────────────────────────────────────────────
Write-Step "Converting OCI → $OutputFormat via bootc-image-builder"

$OutputDir = Join-Path (Get-Location) 'output'
New-Item -ItemType Directory -Force -Path $OutputDir | Out-Null

# Map format to BIB --type value
$BibType = switch ($OutputFormat) {
    'vhdx'  { 'vhd'   }
    'raw'   { 'raw'   }
    'qcow2' { 'qcow2' }
    'wsl2'  { 'wsl2'  }
}

# BIB config -- substitute env vars
$BibConfig = @"
[[customizations.user]]
name = "mios"
password = "$env:MIOS_USER_PASSWORD_HASH"
$(if ($env:MIOS_SSH_PUBKEY) { 'key = "' + $env:MIOS_SSH_PUBKEY + '"' } else { '' })
groups = ["wheel"]
"@
$BibConfigPath = Join-Path $env:TEMP 'mios-bib.toml'
Set-Content -Path $BibConfigPath -Value $BibConfig -Encoding UTF8

docker run --rm --privileged `
    --security-opt label=type:unconfined_t `
    -v "${OutputDir}:/output" `
    -v "/var/run/docker.sock:/var/run/docker.sock" `
    -v "${BibConfigPath}:/config.toml" `
    "ghcr.io/osbuild/bootc-image-builder:latest" `
    --type $BibType `
    --config /config.toml `
    --local `
    $Tag

if ($LASTEXITCODE -ne 0) { Write-Fail "bootc-image-builder failed (exit $LASTEXITCODE)" }

# Rename vhd → vhdx
if ($OutputFormat -eq 'vhdx') {
    $VhdPath  = Join-Path $OutputDir 'disk.vhd'
    $VhdxPath = Join-Path $OutputDir 'disk.vhdx'
    if (Test-Path $VhdPath) {
        Move-Item -Force $VhdPath $VhdxPath
        Write-Ok "Disk image: $VhdxPath"
    }
} else {
    Write-Ok "Disk image: $(Join-Path $OutputDir "disk.$OutputFormat")"
}

Write-Step "Build complete"
Write-Host ""
Write-Host "  Image tag : $Tag"
Write-Host "  Output    : $OutputDir"
if ($OutputFormat -eq 'vhdx') {
    Write-Host ""
    Write-Host "  Import into Hyper-V:"
    Write-Host "    New-VM -Name 'MiOS' -BootDevice VHD -VHDPath '$OutputDir\disk.vhdx' -Generation 2"
}
